	TOWER_BFG_MISSILE_DESCRIPTION_1 = "每隔%$(T('tower_bfg').attacks.list[2].cooldown_base - T('tower_bfg').powers.missile.cooldown_dec * level) * tcd%$秒，发射绝对不会失误、射程超长的跟踪导弹，造成%$(T('missile_bfg').bullet.damage_min + T('tower_bfg').powers.missile.damage_inc * level) * tdmg%$-%$(T('missile_bfg').bullet.damage_max + T('tower_bfg').powers.missile.damage_inc * level) * tdmg%$点伤害与%$T('mod_bfg_stun').modifier.duration%$秒晕眩。导弹命中后，分裂为三枚小导弹，造成1/3伤害与同样晕眩效果。",
	TOWER_BLADE_BLADE_DANCE_DESCRIPTION_1 = "每隔%$T('soldier_blade').timed_attacks.list[1].cooldown%$秒，发动秘技，斩击最多%$T('soldier_blade').powers.blade_dance.hits[level]%$次，每次造成%$T('soldier_blade').powers.blade_dance.damage_min[level] * tdmg%$-%$T('soldier_blade').powers.blade_dance.damage_max[level] * tdmg%$点真实伤害。",
	TOWER_BLADE_PERFECT_PARRY_DESCRIPTION_1 = "受到攻击时有%$T('soldier_blade').dodge.chance + T('soldier_blade').dodge.chance_inc * level%$%的几率进入无敌状态，持续%$T('soldier_blade').dodge.counter_attack.duration%$秒，期间对周围敌人每秒造成%$T('soldier_blade').dodge.counter_attack.damage_min / T('soldier_blade').dodge.counter_attack.damage_every * tdmg%$点真实伤害。",
	TOWER_BLAZING_WATCHER_DISINTEGRATE_DESCRIPTION_1 = "每次造成伤害有%$T('tower_blazing_watcher').powers.disintegrate.proc_chance%$%概率触发溢能聚爆，对敌人造成%$T('blazing_watcher_ray_proc').bullet.damage_min * tdmg%$+%$T('tower_blazing_watcher').powers.disintegrate.damage_pct[level]%$%最大生命值的法术伤害。",
	TOWER_BLAZING_WATCHER_EXPLOSION_DESCRIPTION_1 = "充能强度提高或触发溢能聚爆时，伴随一次爆炸，造成%$T('blazing_watcher_bolt_blast').bullet.damage_min * level * tdmg%$-%$T('blazing_watcher_bolt_blast').bullet.damage_max * level * tdmg%$x充能强度点法术爆炸伤害，并使敌人减速%$1 - T('mod_blazing_watcher_bolt_blast').slow.factor%$%x充能强度，持续%$T('mod_blazing_watcher_bolt_blast').modifier.duration%$秒。",
	TOWER_BONE_FLINGERS_MILK_DESCRIPTION_1 = "攻击伤害提升%$T('tower_bone_flingers').powers.milk.damage_inc[level] * tdmg%$点。",
	TOWER_CATAPULT_SKILL_A_DESCRIPTION_1 = "每%$T('tower_catapult').attacks.list[2].cooldown * tcd%$秒，将焦油桶投向敌群，造成%$T('bullet_catapult_skill_a').bullet.damage_min * tdmg%$-%$T('bullet_catapult_skill_a').bullet.damage_max * tdmg%$点爆炸伤害，并使其减速%$(1 - T('mod_catapult_skill_a_slow').slow_factor_config[level])%$%，持续%$T('aura_catapult_skill_a').aura.duration_conf[level]%$秒。",
	TOWER_CATAPULT_SKILL_B_DESCRIPTION_1 = "投出的石弹现在会在落地不久之后爆炸，对周围的敌人造成%$T('aura_catapult_skill_b_bomb').damage_min_conf[level] * tdmg%$-%$T('aura_catapult_skill_b_bomb').damage_max_conf[level] * tdmg%$点爆炸伤害。",
	TOWER_CATAPULT_SKILL_C_DESCRIPTION_1 = "每%$T('tower_catapult').attacks.list[3].cooldown * tcd%$秒在周边路径设置一枚防卫陷阱。陷阱触发时造成%$T('aura_catapult_skill_c_trap').damage_min_conf[level] * tdmg%$-%$T('aura_catapult_skill_c_trap').damage_max_conf[level] * tdmg%$点物理伤害，并使敌人眩晕%$T('mod_catapult_skill_c_stun').stun_duration_config[level]%$秒。",
	TOWER_CROSSBOWS_SKILL_A_DESCRIPTION_1 = "每隔%$T('tower_crossbows').powers.skill_a.cooldown[level] * tcd%$秒，进入狂暴状态，大幅提升攻击速度并造成普攻%$T('tower_crossbows').powers.skill_a.damage_factor%$倍混合伤害，持续%$T('tower_crossbows').powers.skill_a.duration[level]%$秒。",
	TOWER_CROSSBOWS_SKILL_B_DESCRIPTION_1 = "使攻击附带诅咒，令敌人每%$T('mod_crossbows_skill_b_weak').dps.damage_every%$秒受到%$T('mod_crossbows_skill_b_weak').dps.damage_min*level%$点魔法伤害，持续%$T('mod_crossbows_skill_b_weak').modifier.duration%$秒。重复诅咒时，刷新持续时间并叠加伤害。敌人被诅咒弩手击杀时，触发诅咒爆发，对周围敌人造成%$T('aura_crossbows_skill_b').aura.damage_inc * level * tdmg%$点魔法伤害、施加诅咒，并使他们减速%$(1-T('mod_crossbows_skill_b_slow').slow.factor)%$%。",
	TOWER_CROSSBOWS_SKILL_C_DESCRIPTION_1 = "每%$T('tower_crossbows').powers.skill_c.cooldown[level] * tcd%$秒发射一支强力弩箭，造成%$T('tower_crossbows').powers.skill_c.damage_min[level] * tdmg%$-%$T('tower_crossbows').powers.skill_c.damage_max[level] * tdmg%$点真实伤害。强力弩箭有%$T('tower_crossbows').powers.skill_c.instakill_chance[level]%$%概率秒杀敌人，且每层诅咒提升该概率%$T('tower_crossbows').powers.skill_c.instakill_chance_inc%$%。",
	TOWER_CROSSBOW_EAGLE_DESCRIPTION_1 = "提升%$T('tower_crossbow').attacks.list[3].range + T('tower_crossbow').attacks.list[3].range_inc * level%$范围内防御塔%$T('mod_crossbow_eagle').range_factor + T('mod_crossbow_eagle').range_factor_inc * level - 1%$%的射程与%$(1 - (T('mod_crossbow_eagle').cooldown_factor + T('mod_crossbow_eagle').cooldown_factor_inc * level))%$%攻速，并赋予弩堡%$T('tower_crossbow').attacks.list[1].critical_chance + T('tower_crossbow').attacks.list[1].critical_chance_inc * level%$%的暴击几率。",
	TOWER_CROSSBOW_MULTISHOT_DESCRIPTION_1 = "每隔%$(T('tower_crossbow').attacks.list[2].cooldown) * tcd%$秒，快速射出%$T('tower_crossbow').attacks.list[2].shots + T('tower_crossbow').attacks.list[2].shots_inc * level%$支箭矢，每支造成%$T('multishot_crossbow').bullet.damage_min * tdmg%$至%$T('multishot_crossbow').bullet.damage_max * tdmg%$点枪伤。若目标死亡，在%$T('tower_crossbow').attacks.list[2].near_range_base + T('tower_crossbow').attacks.list[2].near_range_inc * level%$范围内尝试转火。",
	TOWER_CULVERINE_SKILL_A_DESCRIPTION_1 = "每%$T('tower_culverine').attacks.list[2].cooldown * tcd%$秒发射一颗硫磺爆弹，对敌群造成%$T('bullet_culverine_skill_a').damage_min_conf[level] * tdmg%$-%$T('bullet_culverine_skill_a').damage_max_conf[level] * tdmg%$点破魔伤害，并留下硫磺云，降低其中敌人%$T('mod_bullet_culverine_skill_a').magic_armor_red_factor%$%魔法抗性，持续%$T('aura_bullet_culverine_skill_a').aura.duration_conf[level]%$秒。",
	TOWER_CULVERINE_SKILL_B_DESCRIPTION_1 = "每次普通攻击摧毁敌人%$T('mod_bullet_culverine_skill_b').armor_red_factor_conf[level]*100%$点护甲。",
	TOWER_CULVERINE_SKILL_C_DESCRIPTION_1 = "每%$T('tower_culverine').attacks.list[3].cooldown * tcd%$秒全速运转，快速连射%$T('tower_culverine').powers.skill_c.shots[level]%$发弹药。",
	TOWER_DARK_ELF_LVL4_SKILL_BUFF_1_DESCRIPTION = "提升暮光长弓手%$(1 - T('tower_dark_elf_lvl4').powers.skill_buff.cooldown_factor)%$%攻速，并使暮光长弓手每杀死一名敌人，伤害提升%$(T('tower_dark_elf_lvl4').powers.skill_buff.damage_min)%$-%$(T('tower_dark_elf_lvl4').powers.skill_buff.damage_max)%$，攻速额外加快%$(1 - T('tower_dark_elf_lvl4').powers.skill_buff.soul_cooldown_factor)%$%(最多加快攻速%$T('tower_dark_elf_lvl4').powers.skill_buff.soul_cooldown_max_stacks * (1 - T('tower_dark_elf_lvl4').powers.skill_buff.soul_cooldown_factor)%$%)，并使附近随机一座防御塔提升伤害%$T('tower_dark_elf_lvl4').powers.skill_buff.soul_tower_damage_factor%$%。以上效果最多触发%$T('tower_dark_elf_lvl4').powers.skill_buff.max_times_table[level]%$次。",
	TOWER_DARK_ELF_LVL4_SKILL_SOLDIERS_1_DESCRIPTION = "召唤%$T('tower_dark_elf_lvl4').barrack.max_soldiers%$名拥有%$T('tower_dark_elf_lvl4').powers.skill_soldiers.hp[level]%$点生命值，%$T('tower_dark_elf_lvl4').powers.skill_soldiers.armor[level]%$护甲，%$T('tower_dark_elf_lvl4').powers.skill_soldiers.dodge_chance[level]%$闪避概率的暮光骚扰者，每次攻击造成%$(T('tower_dark_elf_lvl4').powers.skill_soldiers.damage_min[level]) * tdmg%$-%$(T('tower_dark_elf_lvl4').powers.skill_soldiers.damage_max[level]) * tdmg%$点物理伤害。",
	TOWER_DARK_KNIGHTS_INSTAKILL_DESCRIPTION_1 = "黑暗骑士每次攻击有%$T('soldier_dark_knight').melee.attacks[2].base_chance + T('soldier_dark_knight').melee.attacks[2].chance_inc * level%$%概率秒杀敌人。",
	TOWER_DARK_KNIGHTS_SPIKE_DESCRIPTION_1 = "黑暗骑士受到近战攻击时，回敬%$T('soldier_dark_knight').powers.spike.spiked_armor_inc * level * tdmg%$点物理伤害。",
	TOWER_DEEP_DEVILS_NET_DESCRIPTION_1 = "每隔%$(T('tower_deep_devils').powers.net.cooldown[level]) * tcd%$秒，海潮战士向敌人掷出捕网，让敌人动掸不得，持续%$({T('mod_deep_devils_net1').modifier.duration, T('mod_deep_devils_net2').modifier.duration})[level]%$秒。",
	TOWER_DEEP_DEVILS_STORM_DESCRIPTION_1 = "召唤乌云持续攻击敌人，每次造成%$({T('ray_storm_deep_devils1'), T('ray_storm_deep_devils2'), T('ray_storm_deep_devils3')})[level].bullet.damage_min * tdmg%$点伤害，并眩晕敌人0.5秒。",
	TOWER_DEMON_PIT_LVL4_BIG_GUY_1_DESCRIPTION = "每隔%$(T('tower_demon_pit_lvl4').powers.big_guy.cooldown[level]) * tcd%$秒，召唤一个拥有%$T('big_guy_tower_demon_pit_lvl4').health_level[level]%$点生命值的大恶魔，其攻击可造成%$(T('big_guy_tower_demon_pit_lvl4').damage_min[level]) * tdmg%$-%$(T('big_guy_tower_demon_pit_lvl4').damage_max[level]) * tdmg%$点物理伤害。爆炸造成%$(T('big_guy_tower_demon_pit_lvl4').explosion_damage[level]) * tdmg%$点伤害。",
	TOWER_DEMON_PIT_LVL4_MASTER_EXPLODERS_2_DESCRIPTION = "小恶魔的爆炸伤害提升%$T('tower_demon_pit_lvl4').powers.master_exploders.explosion_damage_factor[level] - 1%$%，燃烧效果每秒造成%$(T('tower_demon_pit_lvl4').powers.master_exploders.burning_damage_min[level] / T('mod_tower_demon_pit_master_explosion_burning').dps.damage_every) * tdmg%$-%$(T('tower_demon_pit_lvl4').powers.master_exploders.burning_damage_max[level] / T('mod_tower_demon_pit_master_explosion_burning').dps.damage_every) * tdmg%$点真实伤害，持续%$T('tower_demon_pit_lvl4').powers.master_exploders.burning_duration[level]%$秒。",
	TOWER_DRAGONS_LVL4_DRAGON_SPLIT_1_DESCRIPTION = "每隔%$(T('tower_dragons_lvl4').powers.dragon_split.cooldown[level]) * tcd%$秒，发射三枚魔法飞弹，共造成%$(T('tower_dragons_lvl4').attacks.list[3].damage_min[level]) * tdmg%$-%$(T('tower_dragons_lvl4').attacks.list[3].damage_max[level]) * tdmg%$点魔法伤害，并对半径%$T('tower_dragons_lvl4').attacks.list[3].damage_radius[level]%$范围内敌人造成%$(T('tower_dragons_lvl4').attacks.list[3].damage_min_area[level]) * tdmg%$-%$(T('tower_dragons_lvl4').attacks.list[3].damage_max_area[level]) * tdmg%$点魔法伤害。",
	TOWER_DRAGONS_LVL4_MASSIVE_FEAR_1_DESCRIPTION = "每隔%$(T('tower_dragons_lvl4').powers.massive_fear.cooldown[level]) * tcd%$秒，发出震耳欲聋的咆哮，震慑周围敌人，使其晕眩%$T('tower_dragons_lvl4').powers.massive_fear.stun_duration[level]%$秒。",
	TOWER_DROW_BLADE_MAIL_DESCRIPTION_1 = "变节者可将所受伤害的%$T('soldier_drow').powers.blade_mail.spiked_armor_inc * level%$%反弹给面前的敌人。",
	TOWER_DROW_LIFE_DRAIN_DESCRIPTION_1 = "每隔%$T('soldier_drow').melee.attacks[2].cooldown%$秒进行吸血打击，驱散剧毒，造成%$T('soldier_drow').melee.attacks[2].damage_inc * level * tdmg%$点残暴伤害，并使变节者恢复%$T('mod_life_drain_drow').heal_factor%$*伤害+%$T('mod_life_drain_drow').heal_base%$点可溢出生命值。",
	TOWER_DRUID_NATURE_DESCRIPTION_1 = "呼唤%$level%$头拥有%$T('soldier_druid_bear').health.hp_max%$点生命值、%$T('soldier_druid_bear').health.armor * 100%$点护甲、%$T('soldier_druid_bear').health.magic_armor * 100%$点法抗与%$T('soldier_druid_bear').melee.attacks[1].damage_min * tdmg%$-%$T('soldier_druid_bear').melee.attacks[1].damage_max * tdmg%$点攻击力的符文巨熊。",
	TOWER_DRUID_SYLVAN_DESCRIPTION_1 = "每隔%$(T('druid_shooter_sylvan').attacks.list[1].cooldown) * tcd%$秒，诅咒一个敌人，使其每%$T('mod_druid_sylvan').ray_cooldown%$秒受到%$T('mod_druid_sylvan').damage * tdmg * level%$点伤害，并将所受全部伤害的%$T('mod_druid_sylvan').attack.damage_factor[level]%$%传递给身边未被诅咒的敌人，持续%$T('mod_druid_sylvan').modifier.duration%$秒。若敌人死亡且诅咒仍在持续，诅咒效果会延长一秒，并转移到附近敌人身上。",
	TOWER_DWAARP_DRILL_DESCRIPTION_1 = "每隔%$(T('tower_dwaarp').attacks.list[3].cooldown_base + T('tower_dwaarp').attacks.list[3].cooldown_inc * level) * tcd%$秒，向一名生命高于1000的敌人派出自动矿业钻头，将它变成一堆零件。",
	TOWER_DWAARP_LAVA_DESCRIPTION_1 = "每隔%$(T('tower_dwaarp').attacks.list[2].cooldown) * tcd%$秒，造成%$(1 + T('tower_dwaarp').powers.lava.damage_mult_inc * level)%$倍普攻伤害并灼烧范围内所有敌人%$T('lava_dwaarp').aura.duration%$秒，每秒造成%$(T('mod_lava_dwaarp').dps.damage_min+T('mod_lava_dwaarp').dps.damage_inc * level)/T('mod_lava_dwaarp').dps.damage_every*tdmg%$点伤害。燃烧效果持续%$T('mod_lava_dwaarp').modifier.duration%$秒。",
	TOWER_DWARF_LVL4_FORMATION_1_DESCRIPTION = "为小队增加%$level%$名炮兵。",
	TOWER_DWARF_LVL4_INCENDIARY_AMMO_1_DESCRIPTION = "每隔%$T('soldier_tower_dwarf_lvl4').powers.incendiary_ammo.cooldown%$秒，发射一枚爆弹，造成%$(T('bullet_incendiary_soldier_tower_dwarf').bullet.damage_min_config[level]) * tdmg%$-%$(T('bullet_incendiary_soldier_tower_dwarf').bullet.damage_max_config[level]) * tdmg%$点伤害，并使范围内的敌人在%$T('mod_aura_bullet_soldier_tower_dwarf').modifier.duration%$秒内受到%$(T('mod_aura_bullet_soldier_tower_dwarf').dps.damage_config[level] / T('mod_aura_bullet_soldier_tower_dwarf').dps.damage_every * T('mod_aura_bullet_soldier_tower_dwarf').modifier.duration) * tdmg%$点燃烧伤害。",
	TOWER_ELF_BLEED_DESCRIPTION_1 = "使精灵的射击附带流血效果，在三秒内造成%$(T('mod_elf_bleed').dps.damage_min + T('mod_elf_bleed').dps.damage_inc * (level - 1)) * T('mod_elf_bleed').modifier.duration / T('mod_elf_bleed').dps.damage_every * tdmg%$点伤害",
	TOWER_ELF_CRIPPLE_DESCRIPTION_1 = "游侠有%$T('soldier_elf').ranged.attacks[2].chance + T('soldier_elf').ranged.attacks[2].chance_inc * level%$%几率射出精灵箭矢，造成%$(T('arrow_elf_cripple').bullet.damage_min + T('arrow_elf_cripple').bullet.damage_inc * level) * tdmg%$点真实伤害与%$(1 - T('mod_elf_cripple').slow.factor)%$%的减速，持续%$T('mod_elf_cripple').modifier.duration%$秒。",
	TOWER_ELF_RANGER_SKILL_A_DESCRIPTION_1 = "每%$T('tower_elf_ranger').attacks.list[2].cooldown * tcd%$秒连射%$T('tower_elf_ranger').powers.skill_a.arrow_count%$发涂有毒药的箭矢，使目标中毒，在%$T('mod_elf_ranger_skill_a_poison').modifier.duration_config[level]%$秒内持续受到共计%$(T('mod_elf_ranger_skill_a_poison').dps.damage_min + T('mod_elf_ranger_skill_a_poison').dps.damage_inc * level) / T('mod_elf_ranger_skill_a_poison').dps.damage_every * T('mod_elf_ranger_skill_a_poison').modifier.duration_config[level] * tdmg%$点剧毒伤害。",
	TOWER_ELF_RANGER_SKILL_B_DESCRIPTION_1 = "每%$T('tower_elf_ranger').attacks.list[3].cooldown * tcd%$秒射出一发蓄力箭矢，对目标造成%$T('tower_elf_ranger').powers.skill_b.damage_min[level] * tdmg%$-%$T('tower_elf_ranger').powers.skill_b.damage_max[level] * tdmg%$点物理伤害，并使其眩晕%$T('mod_elf_ranger_skill_b_stun').modifier.duration%$秒。同时生长出刺藤，使周围的敌人减速%$(1 - T('mod_elf_ranger_skill_b_slow').slow.factor)%$%，持续%$T('aura_elf_ranger_skill_b').aura.duration_conf[level]%$秒。",
	TOWER_ELF_RANGER_SKILL_C_DESCRIPTION_1 = "箭矢现在可在目标周围的敌人间弹射%$T('bullet_elf_ranger_skill_c_bounce_clone').max_bounces%$次，每次弹射造成先前%$T('tower_elf_ranger').powers.skill_c.bounce_damage_mult[level]%$%的伤害。",
	TOWER_ELVEN_STARGAZERS_LVL4_STARS_DEATH_1_DESCRIPTION = "精灵观星者每轮射击额外攻击%$level%$次，且消灭或传送的目标会爆出%$T('mod_tower_elven_stargazers_star_death').modifier.stars_death_stars[level]%$颗星星，对敌人造成%$(T('arrow_tower_stargazers_death_star').bullet.damage_min_config[level]) * tdmg%$-%$(T('arrow_tower_stargazers_death_star').bullet.damage_max_config[level]) * tdmg%$点魔法伤害。",
	TOWER_ELVEN_STARGAZERS_LVL4_TELEPORT_1_DESCRIPTION = "每隔%$(T('tower_elven_stargazers_lvl4').powers.teleport.cooldown[level]) * tcd%$秒，传送最多%$T('tower_elven_stargazers_lvl4').attacks.list[2].max_targets[level]%$名敌人，使他们倒退一段距离。",
	TOWER_ENTWOOD_CLOBBER_DESCRIPTION_1 = "每隔%$(T('tower_entwood').attacks.list[3].cooldown) * tcd%$秒，震动地面，造成%$T('tower_entwood').powers.clobber.damage_values[level] * tdmg%$点真实伤害与%$(1 - T('mod_clobber_slow').slow.factor)%$%减速，并对较近的敌人造成额外40%伤害与眩晕效果，持续%$T('tower_entwood').powers.clobber.stun_durations[level]%$秒。",
	TOWER_ENTWOOD_FIERY_NUTS_DESCRIPTION_1 = "每隔%$(T('tower_entwood').attacks.list[2].cooldown) * tcd%$秒，投掷一颗燃烧的坚果，造成%$(T('rock_firey_nut').bullet.damage_min + T('rock_firey_nut').bullet.damage_min_inc * level) * tdmg%$点爆炸伤害，并使地面着火。",
	TOWER_EWOK_ARMOR_DESCRIPTION_1 = "提升伊渥克士兵%$T('soldier_ewok').health.armor_inc * level * 100%$点护甲。",
	TOWER_EWOK_SHIELD_DESCRIPTION_1 = "提升盾牌格挡的持续时间至%$T('soldier_ewok').powers.shield.duration_base + level%$秒，减短盾牌格挡的冷却至%$T('soldier_ewok').powers.shield.cooldown_base - level%$秒，并附带%$T('soldier_ewok').powers.shield.heal_inc * level%$点恢复效果。",
	TOWER_EWOK_TEAR_DESCRIPTION_1 = "提升投索伤害%$T('bullet_soldier_ewok').bullet.damage_inc * level * tdmg%$点，并使每发投索降低敌人护甲%$(T('mod_ewok_tear').damage_min+T('mod_ewok_tear').damage_inc*level)*100%$点。",
	TOWER_FAERIE_DRAGON_IMPROVE_SHOT_DESCRIPTION_1 = "提高范围晶化概率至%$T('tower_faerie_dragon').aura_rate_base + T('tower_faerie_dragon').aura_rate_inc * level%$%。",
	TOWER_FAERIE_DRAGON_MORE_DRAGONS_DESCRIPTION_1 = "孵化%$level%$只仙女龙，晶化你的敌人。",
	TOWER_FLAMESPITTER_LVL4_SKILL_BOMB_1_DESCRIPTION = "每隔%$(T('tower_flamespitter_lvl4').powers.skill_bomb.cooldown[level]) * tcd%$秒，发射一枚燃烧弹，造成%$(T('tower_flamespitter_lvl4').attacks.list[2].damage_min[level]) * tdmg%$点爆炸伤害，并灼烧敌人，每秒造成%$(T('mod_burning_tower_flamespitter_skill_bomb').dps.damage_min / T('mod_burning_tower_flamespitter_skill_bomb').dps.damage_every) * tdmg%$点真实伤害，持续%$T('mod_burning_tower_flamespitter_skill_bomb').modifier.duration%$秒。",
	TOWER_FLAMESPITTER_LVL4_SKILL_COLUMNS_2_DESCRIPTION = "每隔%$(T('tower_flamespitter_lvl4').powers.skill_columns.cooldown[level]) * tcd%$秒，地面喷发出火柱，眩晕敌人%$T('mod_tower_flamesplitter_skill_columns').modifier.duration%$秒，并造成%$T('tower_flamespitter_lvl4').powers.skill_columns.damage_out_min[level]*tdmg%$点物理伤害。处于火柱内圈的敌人会额外受到%$T('tower_flamespitter_lvl4').powers.skill_columns.damage_in_min[level]*tdmg%$点真实伤害，并在死亡后化为灰烬。",
	TOWER_FOREST_CIRCLE_DESCRIPTION_1 = "每隔%$T('soldier_forest').timed_attacks.list[1].cooldown%$秒，在%$T('mod_forest_circle').modifier.duration%$秒内治疗自身和150范围内友军%$T('mod_forest_circle').hps.heal_inc * level * T('mod_forest_circle').modifier.duration / T('mod_forest_circle').hps.heal_every%$点生命值。",
	TOWER_FOREST_EERIE_DESCRIPTION_1 = "每隔%$T('soldier_forest').timed_attacks.list[2].cooldown%$秒，以%$T('aura_forest_eerie').roots_count + T('aura_forest_eerie').roots_count_inc * level%$根尖刺蔓藤覆盖一片区域，减速敌人%$1 - T('mod_forest_eerie_slow').slow.factor%$%，每%$T('mod_forest_eerie_dps').modifier.duration%$秒对其造成%$(T('mod_forest_eerie_dps').dps.damage_min + T('mod_forest_eerie_dps').dps.damage_inc * level) * tdmg%$点物理伤害，持续%$T('aura_forest_eerie').aura.duration + T('aura_forest_eerie').aura.duration_inc * level%$秒。",
	TOWER_FOREST_OAK_DESCRIPTION_1 = "赋予森林守护者投掷魔法长矛的能力，造成%$(T('spear_forest_oak').bullet.damage_min + T('spear_forest_oak').bullet.damage_inc * level) * tdmg%$点真实伤害。",
	TOWER_FORGER_SKILL_A_DESCRIPTION_1 = "每隔%$T('tower_forger').attacks.list[2].cooldown * tcd%$秒，召出三枚旋转的能量圆刃沿道路割裂前行，每%$T('decal_forger_skill_a_blade').damage_cycle_time%$秒对命中的敌人造成%$T('tower_forger').powers.skill_a.damage_min[level] * tdmg%$-%$T('tower_forger').powers.skill_a.damage_max[level] * tdmg%$点魔法伤害。",
	TOWER_FORGER_SKILL_B_DESCRIPTION_1 = "每隔%$T('tower_forger').attacks.list[3].cooldown * tcd%$秒，在道路上召唤%$T('tower_forger').attacks.list[3].max_crystals%$颗水晶，每颗每秒造成%$T('tower_forger').powers.skill_b.damage_min[level] / T('bullet_forger_skill_b').hit_cycle_time%$-%$T('tower_forger').powers.skill_b.damage_max[level] / T('bullet_forger_skill_b').hit_cycle_time%$点魔法伤害。水晶在造成总计%$T('tower_forger').powers.skill_b.max_damage[level]%$点伤害，或经过%$T('tower_forger').powers.skill_b.duration[level]%$秒后碎裂。",
	TOWER_FORGER_SKILL_C_DESCRIPTION_1 = "每隔%$T('tower_forger').attacks.list[4].cooldown * tcd%$秒，将最多%$T('tower_forger').powers.skill_c.max_targets[level]%$名敌人束缚在能量监牢中，持续%$T('tower_forger').powers.skill_c.stun_duration[level]%$秒。",
	TOWER_FRANKENSTEIN_LIGHTNING_DESCRIPTION_1 = "增加共%$T('ray_frankenstein').bounces_lvl[level] - T('ray_frankenstein').bounces_lvl[0]%$次闪电打击连锁数，伤害提升共%$T('mod_ray_frankenstein').dps.damage_inc * level * tdmg%$点。",
	TOWER_GHOST_LVL4_EXTRA_DAMAGE_1_DESCRIPTION = "幽灵战士释放死亡光环，对身边敌人每%$T('aura_tower_ghost_extra_damage').aura.cycle_time%$秒造成%$(T('aura_tower_ghost_extra_damage').aura.damage_min + T('aura_tower_ghost_extra_damage').aura.damage_inc * level) * tdmg%$点法术伤害。",
	TOWER_GHOST_LVL4_SOUL_ATTACK_1_DESCRIPTION = "幽灵战士的复活时间减少%$T('soldier_tower_ghost_lvl4').powers.soul_attack.dead_lifetime_dec[level]%$秒，并在被击败后扑向一名敌人，造成%$(T('soul_soldier_tower_ghost_lvl4').damage_min[level]) * tdmg%$点真实伤害，降低其速度并使其攻击伤害减半，持续%$T('mod_tower_ghost_soul_slow').modifier.duration%$秒。",
	TOWER_GOBLIRANG_BEES_DESCRIPTION_1 = "每隔%$(T('tower_goblirang').attacks.list[3].cooldown) * tcd%$秒，掷出一窝毒蜂追踪敌人，每%$T('honey_bees_aura').aura.cycle_time%$秒造成%$(T('mod_honey_bees').dps.damage_min + T('mod_honey_bees').dps.damage_inc * level) * tdmg%$点毒伤，并使周围敌人减速%$1 - T('mod_honey_bees_slow').slow.factor%$%，持续%$T('honey_bees_aura').aura.duration%$秒。",
	TOWER_GOBLIRANG_BIG_DESCRIPTION_1 = "每隔%$(T('tower_goblirang').attacks.list[2].cooldown) * tcd%$秒，掷出一枚巨型回旋镖，造成%$T('tower_goblirang').powers.big.damage_min[level] * tdmg%$-%$T('tower_goblirang').powers.big.damage_max[level] * tdmg%$点物理伤害。",
	TOWER_GRIM_CEMETERY_HANDS_DESCRIPTION_1 = "每隔%$(T('tower_grim_cemetery').powers.hands.cooldown[level]) * tcd%$秒，伸出%$T('tower_grim_cemetery').powers.hands.count%$只手恐吓敌人，使他们逃跑%$T('aura_grim_cemetery_hand').scare_duration%$秒。",
	TOWER_GRIM_CEMETERY_PESTILENCE_DESCRIPTION_1 = "使僵尸死亡时爆炸，对%$T('mod_grim_cemetery_explode').explode_range%$范围敌人造成%$T('mod_grim_cemetery_explode').explode_damage[level] * tdmg%$点法术伤害，并使敌人中毒，在%$T('mod_grim_cemetery_poison').modifier.duration%$秒内每%$T('mod_grim_cemetery_poison').dps.damage_every%$秒受到%$T('mod_grim_cemetery_poison').dps.damage_min * tdmg%$点伤害。",
	TOWER_HERMIT_TOAD_LVL4_JUMP_1_DESCRIPTION = "每隔%$(T('tower_hermit_toad_lvl4').powers.jump.cooldown[level]) * tcd%$秒，隐士会高高跃起，砸在敌人身上，造成%$(T('tower_hermit_toad_lvl4').powers.jump.damage_min[level]) * tdmg%$点伤害，并震晕敌人%$T('mod_tower_hermit_toad_jump').balance_duration[level]%$秒。",
	TOWER_HIGH_ELVEN_SENTINEL_DESCRIPTION_1 = "提升%$T('tower_high_elven').powers.sentinel.range_base + T('tower_high_elven').powers.sentinel.range_inc * level%$范围内防御塔%$T('mod_high_elven').damage_factor + T('mod_high_elven').damage_factor_inc * level%$%伤害与%$1 - (T('mod_high_elven').cooldown_factor + level * T('mod_high_elven').cooldown_factor_inc)%$%攻速。",
	TOWER_HIGH_ELVEN_TIMELAPSE_DESCRIPTION_1 = "每隔%$(T('tower_high_elven').attacks.list[2].cooldown) * tcd%$秒，将最多%$T('tower_high_elven').powers.timelapse.target_count[level]%$个敌人相位传送出战场%$T('mod_timelapse').modifier.duration%$秒，造成%$T('mod_timelapse').damage_levels[level] * tdmg%$点伤害。若敌人在此期间死亡，将召唤一个奥术守卫。该技能优先锁定可被沉默的敌人。",
	TOWER_INFERNAL_MAGE_CURSE_DESCRIPTION_1 = "每隔%$(T('tower_infernal_mage').attacks.list[4].cooldown) * tcd%$秒，诅咒%$T('aura_curse_infernal').aura.radius%$范围内的敌人%$T('mod_infernal_curse_visual').modifier.duration%$秒，使他们每行动%$1 / (T('mod_infernal_curse_effect').damage_per_distance + T('mod_infernal_curse_effect').damage_per_distance_inc * level)%$点距离(基于原速)，就受到1点真实伤害，并烧伤他们。",
	TOWER_INFERNAL_MAGE_FISSURE_DESCRIPTION_1 = "每隔%$(T('tower_infernal_mage').powers.fissure.cooldown_base + T('tower_infernal_mage').powers.fissure.cooldown_inc * level) * tcd%$秒，在%$T('tower_infernal_mage').attacks.list[2].max_spread%$范围内随机召唤%$T('tower_infernal_mage').attacks.list[2].loops%$个岩浆裂隙，每个造成%$T('tower_infernal_mage').powers.fissure.damage_min[level] * tdmg%$-%$T('tower_infernal_mage').powers.fissure.damage_max[level] * tdmg%$点法术伤害。",
	TOWER_INFERNAL_MAGE_TELEPORT_DESCRIPTION_1 = "每隔%$(T('tower_infernal_mage').attacks.list[3].cooldown) * tcd%$秒，将最多%$T('tower_infernal_mage').powers.teleport.max_count[level]%$名敌人向后传送%$-T('mod_teleport_infernal').nodes_offset_min%$个节点，并烧伤他们。",
	TOWER_KNIGHTS_SKILL_A_DESCRIPTION_1 = "每有一位英雄在周围，骑士们便获得%$(T('soldier_knights').powers.skill_a.extra_armor[level])%$%护甲；范围内的英雄同时获得%$(T('soldier_knights').powers.skill_a.hero_damage_factor[level])%$%伤害加成。",
	TOWER_KNIGHTS_SKILL_B_DESCRIPTION_1 = "战斗中每%$T('soldier_knights').timed_attacks.list[1].cooldown%$秒，骑士恢复自身%$(T('soldier_knights').powers.skill_b.hp_ptg[level])%$%的最大生命值，可过量治疗至%$T('soldier_knights').powers.skill_b.hp_overflow_factor%$倍最大生命值。",
	TOWER_KNIGHTS_SKILL_C_DESCRIPTION_1 = "周围有友军阵亡时，骑士继承遗志，普通攻击速度提升%$(1 - T('soldier_knights').powers.skill_c.cd_mult[level])%$%，只可触发一次。",
	TOWER_LIGHT_PRIESTESS_SKILL_A_DESCRIPTION_1 = "每%$T('tower_light_priestess').attacks.list[2].cooldown * tcd%$秒，施展圣光庇佑一群我方单位，使其在%$T('tower_light_priestess').powers.skill_a.duration[level]%$秒内恢复%$T('tower_light_priestess').powers.skill_a.heal_per_second[level] * T('tower_light_priestess').powers.skill_a.duration[level]%$点生命值，并在期间提升%$T('tower_light_priestess').powers.skill_a.armor_inc[level]*100%$点护甲。",
	TOWER_LIGHT_PRIESTESS_SKILL_B_DESCRIPTION_1 = "每%$T('tower_light_priestess').attacks.list[3].cooldown * tcd%$秒，沉默并减速此塔周围的敌人%$(1 - T('tower_light_priestess').powers.skill_b.slow_factor[level])%$%，持续%$T('tower_light_priestess').powers.skill_b.silence_duration[level]%$秒。",
	TOWER_LIGHT_PRIESTESS_SKILL_C_DESCRIPTION_1 = "每%$T('tower_light_priestess').attacks.list[4].cooldown * tcd%$秒，祝福范围内的一座防御塔，使其攻击伤害提升%$(T('tower_light_priestess').powers.skill_c.damage_factor[level] - 1)%$%，持续%$T('tower_light_priestess').powers.skill_c.duration[level]%$秒。",
	TOWER_MECH_MISSILE_DESCRIPTION_1 = "每隔%$T('soldier_mecha').attacks.list[2].cooldown%$秒，齐发%$T('soldier_mecha').attacks.list[2].burst + T('soldier_mecha').attacks.list[2].burst_inc * level%$枚必定命中的追踪导弹，每发造成%$T('missile_mecha').bullet.damage_min * tdmg%$至%$T('missile_mecha').bullet.damage_max * tdmg%$点爆炸伤害。",
	TOWER_MECH_OIL_DESCRIPTION_1 = "每隔%$T('soldier_mecha').attacks.list[3].cooldown%$秒，倾倒废油，减缓地面敌人%$1 - T('mod_slow_oil').slow.factor%$%移速，持续%$T('oil_mecha').aura.duration + T('oil_mecha').aura.duration_inc * level%$秒。",
	TOWER_MELTING_FURNACE_COAL_DESCRIPTION_1 = "每隔%$(T('tower_melting_furnace').attacks.list[2].cooldown) * tcd%$秒，发射%$T('tower_melting_furnace').powers.coal.fragment_count_base + T('tower_melting_furnace').powers.coal.fragment_count_inc * level%$块灼热煤块，落地后形成维持%$T('lava_furnace').aura.duration%$秒的岩浆池，每%$T('lava_furnace').aura.cycle_time%$秒造成%$(T('lava_furnace').aura.damage_min + T('lava_furnace').aura.damage_inc * level) * tdmg%$点物理伤害，并削减敌人%$T('lava_furnace').damage_armor * 100%$点护甲。",
	TOWER_MELTING_FURNACE_HEAT_DESCRIPTION_1 = "为附近%$T('tower_melting_furnace').attacks.list[3].range%$范围内的防御塔提供%$(T('mod_furnace_buff').damage_factor - 1) * level%$%伤害加成。",
	TOWER_MINERS_SKILL_A_DESCRIPTION_1 = "每%$T('tower_miners').attacks.list[1].cooldown * tcd%$秒，矿车疾驰而出冲撞敌群，造成%$T('tower_miners').powers.skill_a.cart_damage_min[level] * tdmg%$-%$T('tower_miners').powers.skill_a.cart_damage_max[level] * tdmg%$点爆炸伤害，并送出2名矮人至道路上战斗%$T('soldier_miners_skill_a').reinforcement.duration%$秒。",
	TOWER_MINERS_SKILL_B_DESCRIPTION_1 = "矮人从地下挖掘而出时，对周围敌人造成%$T('tower_miners').powers.skill_b.damage_min[level] * tdmg%$-%$T('tower_miners').powers.skill_b.damage_max[level] * tdmg%$点物理伤害，并使其眩晕%$(T('mod_miners_skill_b_stun').modifier.duration_base + (level - 1) * T('mod_miners_skill_b_stun').modifier.duration_inc)%$秒。",
	TOWER_MINERS_SKILL_C_DESCRIPTION_1 = "矮人的挖掘速度提升至%$T('tower_miners').powers.skill_c.gold_factor[level]%$%，并且即使在战斗中也不停工。",
	TOWER_MUSKETEER_SHRAPNEL_DESCRIPTION_1 = "每隔%$(T('tower_musketeer').attacks.list[4].cooldown) * tcd%$秒，发射霰弹，对一片区域造成总计%$(T('bomb_musketeer').bullet.damage_min + T('bomb_musketeer').bullet.damage_min_inc * level) * T('tower_musketeer').attacks.list[4].loops * tdmg%$-%$(T('bomb_musketeer').bullet.damage_max + T('bomb_musketeer').bullet.damage_max_inc * level) * T('tower_musketeer').attacks.list[4].loops * tdmg%$点爆炸伤害。敌人较远时，霰弹将会分散，伤害降低%$1 - T('tower_musketeer').powers.shrapnel.far_damage_factor%$%，并使下次霰弹冷却降低%$T('tower_musketeer').powers.shrapnel.far_cooldown_reduction%$%。",
	TOWER_MUSKETEER_SNIPER_DESCRIPTION_1 = "每隔%$(T('tower_musketeer').attacks.list[2].cooldown) * tcd%$秒，精准瞄准生命值最高的敌人，具有%$T('tower_musketeer').powers.sniper.instakill_chance_inc * level%$%几率秒杀或造成最大生命值%$(T('tower_musketeer').powers.sniper.damage_factor_inc * level) * tdmg%$%的枪伤。若目标为boss，则造成普攻%$T('tower_musketeer').powers.sniper.boss_damage_base + T('tower_musketeer').powers.sniper.boss_damage_inc * level%$倍伤害。",
	TOWER_NECROMANCER_LVL4_SKILL_DEBUFF_1_DESCRIPTION = "每隔%$(T('tower_necromancer_lvl4').powers.skill_debuff.cooldown[level]) * tcd%$秒，召唤死亡图腾，持续%$T('tower_necromancer_lvl4').powers.skill_debuff.aura_duration[level]%$秒，诅咒、沉默敌人并使骷髅的攻击伤害提升%$T('aura_tower_necromancer_skill_debuff').modifier_inflicted_damage_factor[level] - 1%$%。",
	TOWER_NECROMANCER_LVL4_SKILL_RIDER_1_DESCRIPTION = "每隔%$(T('tower_necromancer_lvl4').powers.skill_rider.cooldown[level]) * tcd%$秒，召唤一名死亡骑士向前冲锋，对经过的敌人造成%$(T('aura_tower_necromancer_skill_rider').damage_min_config[level]) * tdmg%$点真实伤害。",
	TOWER_NECROMANCER_PESTILENCE_DESCRIPTION_1 = "每隔%$(T('tower_necromancer').attacks.list[2].cooldown) * tcd%$秒，召唤%$level + 2%$团瘟疫云，持续%$level + 3%$秒，使%$T('pestilence').aura.radius%$范围内敌人每秒受到%$(T('mod_pestilence').dps.damage_min / T('mod_pestilence').dps.damage_every) * tdmg%$点的毒素伤害，且伤害下降%$1-T('mod_pestilence_weak').inflicted_damage_factor%$%。",
	TOWER_NECROMANCER_RIDER_DESCRIPTION_1 = "召唤拥有%$T('soldier_death_rider').health.hp_max + T('soldier_death_rider').health.hp_inc * level%$点生命、%$(T('soldier_death_rider').health.armor + T('soldier_death_rider').health.armor_inc * level) * 100%$点护甲、%$(T('soldier_death_rider').melee.attacks[1].damage_min + T('soldier_death_rider').melee.attacks[1].damage_inc * level) * tdmg%$-%$(T('soldier_death_rider').melee.attacks[1].damage_max + T('soldier_death_rider').melee.attacks[1].damage_inc * level) * tdmg%$点攻击力的死亡骑士。死亡骑士能够加持%$T('death_rider_aura').aura.radius%$范围内的亡灵生物，提升他们%$(T('mod_death_rider').extra_armor + T('mod_death_rider').extra_armor_inc * level) * 100%$点护甲与%$(T('mod_death_rider').inflicted_damage_factor + T('mod_death_rider').inflicted_damage_factor_inc * level - 1)%$%攻击力（提升护甲效果对有护甲单位衰减）。",
	TOWER_OGRE_SHIPWRECK_GOBLIN_LAUNCHER_DESCRIPTION_1 = "炮手将哥布林室友加入他的备选炮弹里，每%$(T('tower_ogre_shipwreck').powers.goblin_launcher.cooldown[level]) * tcd%$秒发射一只，战斗%$T('soldier_ogre_shipwreck_red_goblin').health.dead_lifetime%$秒后逃跑。",
	TOWER_ORC_SHAMAN_METEOR_DESCRIPTION_1 = "每隔%$(T('tower_orc_shaman').attacks.list[3].cooldown) * tcd%$秒降下%$T('tower_orc_shaman').attacks.list[3].loops_base + T('tower_orc_shaman').attacks.list[3].loops_inc * level%$颗陨石，每颗在%$T('fireball_orc_shaman_meteorite').bullet.damage_radius%$范围内造成%$(T('fireball_orc_shaman_meteorite').bullet.damage_min + T('fireball_orc_shaman_meteorite').bullet.damage_min_inc * level) * tdmg%$-%$(T('fireball_orc_shaman_meteorite').bullet.damage_max + T('fireball_orc_shaman_meteorite').bullet.damage_max_inc * level) * tdmg%$点法术伤害，并短暂眩晕敌人。",
	TOWER_ORC_SHAMAN_SHOCK_DESCRIPTION_1 = "普攻附带连锁震击，对%$T('bolt_orc_shaman_shock').bullet.damage_radius%$范围内敌人造成%$T('tower_orc_shaman').powers.shock.damage_min[level] * tdmg%$-%$T('tower_orc_shaman').powers.shock.damage_max[level] * tdmg%$点法术伤害。",
	TOWER_ORC_SHAMAN_VINES_DESCRIPTION_1 = "每隔%$(T('tower_orc_shaman').attacks.list[2].cooldown) * tcd%$秒，召唤驻场%$T('aura_orc_shaman_healing_roots').aura.duration%$秒的根须治疗受伤的友军和敌军，每%$T('mod_orc_shaman_heal').hps.heal_every%$秒恢复%$T('mod_orc_shaman_heal').hps.heal_inc * level%$点生命。敌军治疗期间，受伤效果^%$T('mod_orc_shaman_heal_enemy').damage_exponent + T('mod_orc_shaman_heal_enemy').damage_exponent_inc * level%$，法术易伤效果乘以%$T('mod_orc_shaman_heal_enemy').damage_factor_magical + T('mod_orc_shaman_heal_enemy').damage_factor_magical_inc * level%$，速度减慢%$1 - T('mod_orc_shaman_heal_enemy').slow.factor%$%。",
	TOWER_ORC_WARRIORS_BLOODLUST_DESCRIPTION_1 = "兽人勇士的伤害提升%$T('tower_orc_warriors').powers.bloodlust.damage_factor[level] - 1%$%。",
	TOWER_ORC_WARRIORS_SEAL_DESCRIPTION_1 = "兽人勇士每秒恢复%$T('soldier_orc_warrior').powers.seal.heal[level]%$点生命值。",
	TOWER_PALADIN_COVENANT_LVL4_HEALING_PRAYER_1_DESCRIPTION = "每隔%$(T('tower_paladin_covenant_soldier_lvl4').powers.healing_prayer.cooldown[level]) * tcd%$秒，当圣骑士的生命值低于%$T('tower_paladin_covenant_soldier_lvl4').powers.healing_prayer.health_trigger_factor[level]%$%时或受到致命伤时，他将获得无敌，并每秒恢复%$T('tower_paladin_covenant_soldier_lvl4_healing_mod').hps.heal_min[level] / T('tower_paladin_covenant_soldier_lvl4_healing_mod').hps.heal_every%$点生命值，持续%$T('tower_paladin_covenant_soldier_lvl4_healing_mod').modifier.duration%$秒。祷告结束时，圣骑士击退%$T('tower_paladin_covenant_soldier_lvl4').timed_attacks.list[1].beat_back_radius%$范围内的敌人%$T('tower_paladin_covenant_soldier_lvl4').timed_attacks.list[1].beat_back_distance%$点距离，并造成%$T('tower_paladin_covenant_soldier_lvl4').powers.healing_prayer.beat_back_damage_value[level]%$点法术爆炸伤害。",
	TOWER_PALADIN_HEALING_DESCRIPTION_1 = "圣骑士每隔%$T('soldier_paladin').timed_actions.list[1].cooldown%$秒能呼唤圣光，驱散毒瘴，治疗自己%$T('mod_healing_paladin').hps.heal_min_inc * level%$-%$T('mod_healing_paladin').hps.heal_max_inc * level%$点生命值。该治疗可溢出。",
	TOWER_PALADIN_HOLYSTRIKE_DESCRIPTION_1 = "圣骑士有%$T('soldier_paladin').melee.attacks[3].chance + T('soldier_paladin').melee.attacks[3].chance_inc * level%$%概率发动神圣打击，造成%$(T('soldier_paladin').melee.attacks[3].damage_min + T('soldier_paladin').melee.attacks[3].damage_min_inc * level) * tdmg%$-%$(T('soldier_paladin').melee.attacks[3].damage_max + T('soldier_paladin').melee.attacks[3].damage_max_inc * level) * tdmg%$点范围法术爆炸伤害与%$T('mod_paladin_silence').modifier.duration%$秒沉默效果。",
	TOWER_PANDAS_LVL4_TELEPORT_1_DESCRIPTION = "每隔%$T('soldier_tower_pandas_red_lvl4').powers.teleport.cooldown[level]%$秒，发射火焰弹，造成%$(T('soldier_tower_pandas_red_lvl4').powers.teleport.damage_min[level]) * tdmg%$-%$(T('soldier_tower_pandas_red_lvl4').powers.teleport.damage_max[level]) * tdmg%$点真实伤害，并将命中的敌人沿路径往回传送。",
	TOWER_PANDAS_LVL4_THUNDER_1_DESCRIPTION = "每隔%$T('soldier_tower_pandas_blue_lvl4').powers.thunder.cooldown[level]%$秒，召唤雷电进行小范围攻击，每道雷电造成%$(T('soldier_tower_pandas_blue_lvl4').powers.thunder.damage_min[level]) * tdmg%$-%$(T('soldier_tower_pandas_blue_lvl4').powers.thunder.damage_max[level]) * tdmg%$点范围真实伤害，并眩晕命中的敌人%$T('mod_soldier_tower_pandas_blue_stun').modifier.duration%$秒。",
	TOWER_PIRATE_WATCHTOWER_PARROT_DESCRIPTION_1 = "训练%$level%$只鹦鹉投送炸弹，造成%$T('pirate_watchtower_bomb').bullet.damage_min * tdmg%$-%$T('pirate_watchtower_bomb').bullet.damage_max * tdmg%$点爆炸伤害与%$T('mod_pirate_watchtower_bomb').modifier.duration%$秒晕眩。",
	TOWER_PIRATE_WATCHTOWER_REDUCE_COOLDOWN_DESCRIPTION_1 = "提升防御塔%$1 - T('tower_pirate_watchtower').powers.reduce_cooldown.values[level] / T('tower_pirate_watchtower').attacks.list[1].cooldown%$%攻击速度。",
	TOWER_PIRATE_WATCHTOWER_WATCHER_DESCRIPTION_1 = "提升%$T('tower_pirate_watchtower').powers.watcher.range%$范围内防御塔%$T('mod_pirate_watcher').range_factor_inc * level%$%的射程。",
	TOWER_PIXIE_CREAM_DESCRIPTION_1 = "添加%$level%$名侏儒。",
	TOWER_PIXIE_TOTAL_DESCRIPTION_1 = "提升解体法术出现的概率%$T('tower_pixie').powers.total.chances[4][level]%$%。",
	TOWER_RANGER_POISON_DESCRIPTION_1 = "毒素在%$T('mod_ranger_poison').modifier.duration%$秒内造成%$(T('mod_ranger_poison').dps.damage_min + T('mod_ranger_poison').dps.damage_inc * level) * T('mod_ranger_poison').modifier.duration / T('mod_ranger_poison').dps.damage_every * tdmg%$点伤害。中毒敌人减速%$1 - T('mod_ranger_poison').slow.factor%$%，可叠加%$T('mod_ranger_poison').modifier.max_duplicates%$层。中毒的敌人会多被荆棘捆绑%$level * T('mod_thorn').modifier.duration_inc * 0.5%$秒。",
	TOWER_RANGER_THORN_DESCRIPTION_1 = "每隔%$(T('aura_ranger_thorn').aura.cooldown) * tcd%$秒，召唤荆刺和蔓藤，困住最多%$T('aura_ranger_thorn').aura.max_count + T('aura_ranger_thorn').aura.max_count_inc * level%$名敌人并造成每秒%$T('mod_thorn').damage_min / T('mod_thorn').damage_every * tdmg%$点物理伤害，持续%$T('mod_thorn').modifier.duration + T('mod_thorn').modifier.duration_inc * level%$秒。",
	TOWER_RAY_LVL4_CHAIN_1_DESCRIPTION = "魔法射线额外连锁%$T('bullet_tower_ray_chain').max_enemies - 1%$名敌人，使其减速，并造成总魔法伤害的%$T('tower_ray_lvl4').powers.chain.damage_mult[level]%$%。",
	TOWER_ROCKET_GUNNERS_LVL4_PHOSPHORIC_1_DESCRIPTION = "火箭枪手的攻击造成破甲伤害，并附带%$(T('soldier_tower_rocket_gunners_lvl4').melee.attacks[2].damage_area_min[level]) * tdmg%$-%$(T('soldier_tower_rocket_gunners_lvl4').melee.attacks[2].damage_area_max[level]) * tdmg%$点范围伤害与短暂的范围减速效果。",
	TOWER_ROCKET_GUNNERS_LVL4_STING_MISSILES_1_DESCRIPTION = "每隔%$(T('tower_rocket_gunners_lvl4').powers.sting_missiles.cooldown[level]) * tcd%$秒，发射一枚导弹，斩杀一名生命值高于500，低于%$T('soldier_tower_rocket_gunners_lvl4').powers.sting_missiles.kill_hp_factor[level]%$%的敌人。",
	TOWER_ROCKET_RIDERS_ENGINE_DESCRIPTION_1 = "火箭伤害提升%$T('tower_rocket_riders').powers.engine.damage_inc[level] * tdmg%$点，并在爆炸后碎裂成%$T('tower_rocket_riders').powers.engine.fragment_count[level]%$枚破片继续飞行，每片造成%$T('bomb_rr_fragment').bullet.damage_min * tdmg%$-%$T('bomb_rr_fragment').bullet.damage_max * tdmg%$点爆炸伤害。",
	TOWER_ROCKET_RIDERS_MINE_DESCRIPTION_1 = "每%$(T('rr_mine_box').attacks.list[1].cooldown) * tcd%$秒往路上扔一颗磁吸地雷，自动探寻经过的敌人，造成%$T('bomb_rr_mine').bullet.damage_config[level] * tdmg%$点爆炸伤害，并眩晕敌人%$T('mod_rr_mine_stun').modifier.duration%$秒。",
	TOWER_ROCKET_RIDERS_NITRO_DESCRIPTION_1 = "每隔%$(T('tower_rocket_riders').attacks.list[2].cooldown) * tcd%$秒，射出一辆由硝酸甘油推动的火箭，额外造成%$T('tower_rocket_riders').powers.nitro.damage_inc[level] * tdmg%$点爆炸伤害，并能炸出额外%$T('tower_rocket_riders').powers.nitro.fragment_count_inc%$枚破片。",
	TOWER_ROTTEN_FOREST_TREE_DESCRIPTION_1 = "每隔%$(T('tower_rotten_forest').powers.tree.cooldown + T('tower_rotten_forest').powers.tree.cooldown_inc * level) * tcd%$秒，召唤%$T('tower_rotten_forest').powers.tree.count%$只拥有%$T('soldier_rotten_forest_tree').health.hp_max%$点生命值的树精拦截敌人。树精每%$T('mod_soldier_rotten_forest_tree_lose_hp').dps.damage_every%$秒失去%$T('mod_soldier_rotten_forest_tree_lose_hp').dps.damage_min%$点生命值。",
	TOWER_ROTTEN_FOREST_WARP_DESCRIPTION_1 = "每隔%$(T('aura_rotten_forest_thorn').aura.cooldown) * tcd%$秒，召唤草根捆绑最多%$T('aura_rotten_forest_thorn').aura.max_count%$名敌人，持续%$T('mod_rf_thorn').modifier.duration + T('mod_rf_thorn').modifier.duration_inc * level%$秒。",
	TOWER_ROYAL_ARCHERS_LVL4_ARMOR_PIERCER_1_DESCRIPTION = "每隔%$(T('tower_royal_archers_lvl4').powers.armor_piercer.cooldown[level]) * tcd%$秒，射出三支无视敌人%$T('arrow_armor_piercer_royal_archers').bullet.reduce_armor[level]%$护甲的强化箭矢，每支造成%$(T('arrow_armor_piercer_royal_archers').bullet.damage_min_config[level]) * tdmg%$-%$(T('arrow_armor_piercer_royal_archers').bullet.damage_max_config[level]) * tdmg%$点刺击伤害，并降低敌人%$T('mod_tower_royal_archers_armor_piercer').damage_min * 100%$点护甲。",
	TOWER_ROYAL_ARCHERS_LVL4_RAPACIOUS_HUNTER_1_DESCRIPTION = "召唤一只战鹰巡逻，提升皇家弓箭手的视野至%$T('tower_royal_archers_lvl4').powers.rapacious_hunter.attack_range_factor[level]%$倍，并攻击%$T('tower_royal_archers_lvl4').powers.rapacious_hunter.range_config[level]%$范围内的敌人，造成%$(T('tower_royal_archers_lvl4').powers.rapacious_hunter.damage_min[level]) * tdmg%$-%$(T('tower_royal_archers_lvl4').powers.rapacious_hunter.damage_max[level]) * tdmg%$点物理伤害。战鹰会优先攻击施法者，使其获得嘲讽。",
	TOWER_SANDWORM_EAT_DESCRIPTION_1 = "每隔%$(T('tower_sandworm').powers.eat.cooldown[level]) * tcd%$秒，沙虫破土而出，吞噬%$T('controller_tower_sandworm_eat').radius%$范围内所有的非boss单位。当视野内无高于%$BIG_ENEMY_HP%$点生命值的敌人时，沙虫不会释放该技能。",
	TOWER_SANDWORM_SLIME_DESCRIPTION_1 = "每隔%$(T('tower_sandworm').powers.slime.cooldown[level]) * tcd%$秒，射出一枚粘液球，制造一坨持续%$T('aura_bomb_tower_sandworm_spit').aura.duration%$秒的、黏糊糊的区域，使%$T('aura_bomb_tower_sandworm_spit').aura.radius%$范围内的敌人减速%$1 - (T('mod_tower_sandworm_slow').slow.factor + T('mod_tower_sandworm_slow').slow.factor_inc * level)%$%，并施加中毒效果，每%$T('mod_tower_sandworm_poison').dps.damage_every%$秒造成%$(T('mod_tower_sandworm_poison').dps.damage_inc * level) * tdmg%$点伤害。",
	TOWER_SAND_LVL4_SKILL_BIG_BLADE_1_DESCRIPTION = "每隔%$(T('tower_sand_lvl4').powers.skill_big_blade.cooldown) * tcd%$秒，发射旋转刀刃，每秒造成%$(T('tower_sand_lvl4').powers.skill_big_blade.damage_min[level] / T('aura_tower_sand_skill_big_blade').aura.cycle_time) * tdmg%$-%$(T('tower_sand_lvl4').powers.skill_big_blade.damage_max[level] / T('aura_tower_sand_skill_big_blade').aura.cycle_time) * tdmg%$点刺伤，并使敌人减速%$1 - T('mod_tower_sand_skill_big_blade_slow').slow.factor%$%，持续%$T('tower_sand_lvl4').powers.skill_big_blade.duration[level]%$秒。",
	TOWER_SAND_LVL4_SKILL_GOLD_2_DESCRIPTION = "每隔%$(T('tower_sand_lvl4').powers.skill_gold.cooldown) * tcd%$秒，投掷一枚弹射镖刃，对敌人造成%$(T('bullet_tower_sand_skill_gold').bullet.damage_min_config[level]) * tdmg%$点刺伤，被镖刃击杀的敌人会额外产生%$T('bullet_tower_sand_skill_gold').gold_extra[level]%$枚金币",
	TOWER_SENTRY_SKILL_A_DESCRIPTION_1 = "弹夹容量提升至%$T('tower_sentry').powers.skill_a.magazine[level]%$发，可在不换弹的情况下连续射击。",
	TOWER_SENTRY_SKILL_B_DESCRIPTION_1 = "攻击使敌人流血，在%$T('tower_sentry').powers.skill_b.bleed_duration%$秒内造成%$T('tower_sentry').powers.skill_b.bleed_damage_min[level] * T('tower_sentry').powers.skill_b.bleed_duration / T('tower_sentry').powers.skill_b.bleed_cycle_time%$-%$T('tower_sentry').powers.skill_b.bleed_damage_max[level] * T('tower_sentry').powers.skill_b.bleed_duration / T('tower_sentry').powers.skill_b.bleed_cycle_time%$点真实伤害；与敌人的每1点距离提供%$1/T('tower_sentry').powers.skill_b.distance_scale%$%伤害加成。",
	TOWER_SENTRY_SKILL_C_DESCRIPTION_1 = "每隔%$T('tower_sentry').powers.skill_c.cooldown[level]*tcd%$秒，召唤忠诚的看门犬，短暂阻挡并攻击防御塔盲区内的敌人3次，造成%$T('tower_sentry').powers.skill_c.damage_min[level]*3%$-%$T('tower_sentry').powers.skill_c.damage_max[level]*3%$点物理伤害。",
	TOWER_SHADOW_ARCHER_BLADE_DESCRIPTION_1 = "暗影弓手每%$(T('tower_shadow_archer').attacks.list[2].cooldowns[level]) * tcd%$秒会突然消失，刺杀敌军生命最高的敌人。若目标为施法者，恢复%$T('tower_shadow_archer').powers.blade.caster_cooldown_refund%$%冷却。",
	TOWER_SHADOW_ARCHER_CROW_DESCRIPTION_1 = "召唤%$level%$只乌鸦啄击敌人，每次造成%$T('shadow_crow').custom_attack.damage_min * tdmg%$-%$T('shadow_crow').custom_attack.damage_max * tdmg%$点物理伤害，并削减敌人%$T('shadow_crow').damage_armor * 100%$点护甲。",
	TOWER_SHADOW_ARCHER_MARK_DESCRIPTION_1 = "每隔%$(T('tower_shadow_archer').attacks.list[3].cooldown) * tcd%$秒向一名敌人射出一支标记箭，令敌人获得%$T('mod_arrow_shadow_mark').modifier.received_damage_factors[level]%$倍易伤，持续%$T('mod_arrow_shadow_mark').modifier.durations[level]%$秒。该技能优先对生命值高于%$T('tower_shadow_archer').powers.mark.hp_threshold%$的敌人释放。",
	TOWER_SHAOLIN_TOTAL_DESCRIPTION_1 = "将僧众人数升至%$T('tower_shaolin').powers.total.base_count + level%$名。",
	TOWER_SILVER_MARK_DESCRIPTION_1 = "每隔%$(T('tower_silver').attacks.list[3].cooldown_base + T('tower_silver').attacks.list[3].cooldown_inc * level) * tcd%$秒，标记生命值最高的目标，使其易伤提高%$T('mod_arrow_silver_mark').received_damage_factor - 1%$%，持续%$T('mod_arrow_silver_mark').modifier.durations[level]%$秒。所有黄金长弓手将优先攻击被标记目标，且血色审判触发概率提高%$T('tower_silver').powers.mark.sentence_chance_factor - 1%$%。",
	TOWER_SILVER_SENTENCE_DESCRIPTION_1 = "黄金长弓手有%$T('tower_silver').powers.sentence.chances[2][level]%$%/%$T('tower_silver').powers.sentence.chances[1][level]%$%概率进行血色审判，提高%$T('arrow_silver_sentence').bullet.reduce_armor * 100%$点物理穿透，破坏敌人护盾并造成%$T('tower_silver').powers.sentence.damage_factor_base + T('tower_silver').powers.sentence.damage_factor_inc * level%$倍伤害（对boss衰减%$1 - 1 / T('tower_silver').powers.sentence.boss_damage_factor%$%）。",
