	TOWER_SORCERER_POLYMORPH_DESCRIPTION_1 = "每隔%$(T('tower_sorcerer').powers.polymorph.cooldown_base + T('tower_sorcerer').powers.polymorph.cooldown_inc * level) * tcd%$秒，将敌人变形为继承%$T('mod_polymorph_sorcerer').polymorph.transfer_health_factor%$%生命值的绵羊。绵羊非常脆弱，但无法阻截。",
