	TOWER_STAGE_214_BLACKSMITH_SKILL_A_1_DESCRIPTION = "为附近的单位提供 %$T('mod_stage_214_blacksmith_armor_units_lvl' .. level).armor_buff.max_factor%$% 额外护甲与 %$(T('mod_stage_214_blacksmith_damage_units_lvl' .. level).inflicted_damage_factor - 1)%$% 额外伤害。",
