	TOWER_SUNRAY_MASTER_SKILL_A_DESCRIPTION_1 = "召唤%$level%$个小型土元素与敌人战斗。元素拥有%$T('soldier_sunray_master').health.hp_max%$点生命值，%$T('soldier_sunray_master').health.armor * 100%$点护甲，且可造成%$T('soldier_sunray_master').melee.attacks[1].damage_min%$-%$T('soldier_sunray_master').melee.attacks[1].damage_max%$点物理伤害。",
