	HERO_MECHA_DESCRIPTION = "奥纳格罗源自两位疯狂哥布林发明家的奇思妙想，并以窃取的矮人科技作为基础打造而成，是哥布林战争机器的终极形态，对黑暗军的敌人来说，这是令人畏惧的存在。",
	HERO_MECHA_NAME = "奥纳格罗",
