	HERO_NAGA_DESCRIPTION = "很久之前，骄傲自矜的深渊恶魔曾黯然落败，但维兹南的呼唤，给了它们救赎的机会。征服者浚湃自效忠维兹南后，便随时做好了上阵杀敌的准备，屠戮四方，绝不留情。",
	HERO_NAGA_NAME = "浚湃",
