	HERO_ONI_DESCRIPTION = "冷酷无情的武士， 不知疲倦地寻求复仇。身着黑暗荣誉武士甲， 手执烈焰熊熊武士刀， 光听到他的名字， 就让恶魔军队闻风丧胆。 任何对鬼侍的抵抗，都会化为他复仇的剑阵！",
	HERO_ONI_NAME = "鬼侍",
	HERO_ONI_SPECIAL = "灭魂斩， 千本刃， 复仇怒火",
	HERO_ORC_DESCRIPTION = "维鲁克是一位备受尊敬的兽人部落勇士，曾经为了支持好战分子中的一位领袖，毅然逃出角斗坑，摆脱了自己奴隶的身份。重获自由的他，目前正致力于援助他那些身陷困境的绿皮同僚。",
	HERO_ORC_NAME = "维鲁克",
	HERO_ORC_SPECIAL = "战之欲，角斗立场，蛮力，瞄准砍击，振臂一呼，好战分子",
	HERO_PHOENIX_DESCRIPTION = "传说中的凤凰，能在烈焰中重生。它的火焰能净化一切邪恶。",
	HERO_PHOENIX_NAME = "凤凰",
	HERO_PHOENIX_SPECIAL = "净化，焚祭，余烬之地，炽焰后裔，火焰之环",
	HERO_PIRATE_DESCRIPTION = "酷爱寻宝的海盗船长，众海盗的首领，极其擅长打扫战场。来点金币？",
	HERO_PIRATE_NAME = "黑棘船长",
	HERO_PIRATE_SPECIAL = "火药子母，克拉肯之触，寻宝",
	HERO_PRIEST_DESCRIPTION = "坚韧而辉煌的圣光祭司，以圣光疗愈将士，以光翼庇护战阵，以祝颂铸就壁垒。她的光辉洒满战场，为将士点燃希望。",
	HERO_PRIEST_NAME = "德得尔",
	HERO_PRIEST_SPECIAL = "圣光术，神圣祝颂，光翼庇护",
	HERO_RAELYN_DESCRIPTION = "威风凛凛的蕾琳生来就是为了率领黑暗骑士冲锋陷阵。她的残酷与不屈赢得了维兹南的认可，也令利尼维亚人闻风丧胆。好勇斗狠的她成为了第一位自愿加入黑暗巫师麾下的人。",
	HERO_RAELYN_NAME = "蕾琳",
	HERO_RAELYN_SPECIAL = "指挥号令，残酷打击，全力猛攻，闻风丧胆，坚不可摧",
	HERO_RAELYN_ULTIMATE_ENTITY_NAME = "黑暗骑士",
	HERO_RAG_DESCRIPTION = "瑞兹是个吵吵闹闹的侏儒魔法师，总是乐衷于把各种东西变成布偶。至于他身下的大瑞格是怎么来的？谁也不知道!",
	HERO_RAG_NAME = "瑞兹与大瑞格",
	HERO_RAG_SPECIAL = "爆炸兔兔，敲敲敲，侏儒之怒，布偶变，超级变变变",
	HERO_REGSON_DESCRIPTION = "曾经是暮光精灵的王子，现在是毁家灭国的复仇者，雷格森的利刃和他的怒火一样永不停息。",
	HERO_REGSON_NAME = "雷格森",
	HERO_REGSON_SPECIAL = "刃舞，死战之志，异能魔刃，影袭，死吻",
	HERO_ROBOT_DESCRIPTION = "黑暗大军的锻造大师们突破极限，创造出一台名为“战争巨头”的战争机械。这台由炽热引擎驱动的无情机器在战场上横扫一切，无论友军还是敌人都不会放在眼里。",
	HERO_ROBOT_NAME = "战争巨头",
	HERO_ROBOT_SPECIAL = "震撼冲击，瓦斯烟幕，战争献祭，强力勾拳，列车炮",
	HERO_ROOM_10YR_BUFFED_2_DESC = "在钢铁状态下，天十每隔%$ ((T('hero_10yr')).timed_attacks.list[3].cooldown) %$秒高高跃起，对%$ ((T('hero_10yr')).timed_attacks.list[3].damage_radius) %$范围内敌人造成%$ damage_str(((T('hero_10yr')).hero.skills.buffed).bomb_damage_min[(levels((T('hero_10yr')).hero.skills.buffed))],((T('hero_10yr')).hero.skills.buffed).bomb_damage_max[(levels((T('hero_10yr')).hero.skills.buffed))],(T('hero_10yr')).timed_attacks.list[3].damage_type) %$，同时震碎地面，激起%$ (((T('hero_10yr')).hero.skills.buffed).bomb_steps[(levels((T('hero_10yr')).hero.skills.buffed))]) %$片裂片，每片裂片对%$ ((T('aura_10yr_bomb')).aura.damage_radius) %$范围内敌人造成%$ damage_str(((T('hero_10yr')).hero.skills.buffed).bomb_step_damage_min[(levels((T('hero_10yr')).hero.skills.buffed))],((T('hero_10yr')).hero.skills.buffed).bomb_step_damage_max[(levels((T('hero_10yr')).hero.skills.buffed))],(T('aura_10yr_bomb')).aura.damage_type) %$，并有%$ rate_str(((T('aura_10yr_bomb')).aura.stun_chance)) %$使其眩晕%$ ((E:get_template('mod_10yr_stun')).modifier.duration) %$秒。",
	HERO_ROOM_10YR_BUFFED_2_NAME = "巨叟撼地",
	HERO_ROOM_10YR_BUFFED_DESC = "每隔%$ ((T('hero_10yr')).timed_attacks.list[2].cooldown) %$秒，若周围敌人数量不少于%$ ((T('hero_10yr')).timed_attacks.list[2].min_count) %$，天十进入钢铁状态，移速提升至%$ ((T('hero_10yr')).motion.max_speed_buffed) %$。并免疫基础伤害类型，持续%$ (((T('hero_10yr')).hero.skills.buffed).duration[(levels((T('hero_10yr')).hero.skills.buffed))]) %$秒。在钢铁状态下，天十每隔%$ ((T('hero_10yr')).melee.attacks[3].cooldown) %$秒高速旋转，对%$ ((T('hero_10yr')).melee.attacks[3].damage_radius) %$范围内敌人进行%$ ((T('hero_10yr')).melee.attacks[3].loops) %$连击，每次攻击造成%$ damage_str(((T('hero_10yr')).hero.skills.buffed).spin_damage_min[(levels((T('hero_10yr')).hero.skills.buffed))],((T('hero_10yr')).hero.skills.buffed).spin_damage_max[(levels((T('hero_10yr')).hero.skills.buffed))],(T('hero_10yr')).melee.attacks[3].damage_type) %$。在调集距离较远时，天十将主动退出钢铁状态，返还对应冷却，并传送至调集位置。该技能在钢铁状态下不进入冷却。",
	HERO_ROOM_10YR_BUFFED_NAME = "钢铁时间",
	HERO_ROOM_10YR_RAIN_DESC = "%$ cooldown_str(((T('hero_10yr')).timed_attacks.list[1].cooldown)) %$天十感召天地，召唤%$ (((T('hero_10yr')).hero.skills.rain).loops[(levels((T('hero_10yr')).hero.skills.rain))]) %$枚火球，每枚火球对%$ ((T('fireball_10yr')).bullet.damage_radius) %$范围内敌人造成%$ damage_str(((T('hero_10yr')).hero.skills.rain).damage_min[(levels((T('hero_10yr')).hero.skills.rain))],((T('hero_10yr')).hero.skills.rain).damage_max[(levels((T('hero_10yr')).hero.skills.rain))],(T('fireball_10yr')).bullet.damage_type) %$。火球落地后产生焦土，每隔%$ ((T('power_scorched_water')).aura.cycle_time) %$秒对%$ ((T('power_scorched_water')).aura.radius) %$范围内敌人造成%$ damage_str((T('power_scorched_water')).aura.damage_min,(T('power_scorched_water')).aura.damage_max,(T('power_scorched_water')).aura.damage_type) %$，持续%$ ((T('power_scorched_water')).aura.duration) %$秒。每隔双倍冷却，天十还会释放一次本技能的增强版本，召唤一坨两倍大小的火球。",
	HERO_ROOM_10YR_RAIN_NAME = "火焰冲刺",
	HERO_ROOM_ALIEN_ABDUCTION_DESC = "%$ cooldown_str(((T('hero_alien')).timed_attacks.list[1].cooldown)) %$沙塔呼叫母舰，随机劫持最多%$ (((T('hero_alien')).hero.skills.abduction).total_targets[(levels((T('hero_alien')).hero.skills.abduction))]) %$名血量总和不超过%$ (((T('hero_alien')).hero.skills.abduction).total_hp[(levels((T('hero_alien')).hero.skills.abduction))]) %$的敌人，或一名血量不限的敌人，直接将他们移出战场。",
	HERO_ROOM_ALIEN_ABDUCTION_NAME = "母舰劫持",
