	HERO_ROOM_LAVA_TEMPER_TANTRUM_DESC = "%$ cooldown_str((((T('hero_lava')).hero.skills.temper_tantrum).cooldown[levels((T('hero_lava')).hero.skills.temper_tantrum)])) %$喀拉托连续猛击一名敌人三次，每次造成%$ damage_str(table.tail({19, 35, 54}),table.tail({28, 52, 80}),2) %$，并将目标击晕%$ (2) %$秒。",
