	HERO_ROOM_LAVA_WILD_ERUPTION_NAME = "烈炎席卷",
	HERO_ROOM_LILITH_INFERNAL_WHEEL_DESC = "%$ cooldown_str((((T('hero_lilith')).timed_attacks.list[1]).cooldown)) %$莉莉丝召唤一片持续%$ ((T('aura_lilith_infernal_wheel')).aura.duration) %$秒的火场，使%$ ((T('aura_lilith_infernal_wheel')).aura.radius) %$范围内敌人烧伤，每%$ (T('mod_lilith_infernal_wheel').dps.damage_every) %$秒造成%$ damage_str(((T('hero_lilith')).hero.skills.infernal_wheel).damage[levels((T('hero_lilith')).hero.skills.infernal_wheel)],((T('hero_lilith')).hero.skills.infernal_wheel).damage[levels((T('hero_lilith')).hero.skills.infernal_wheel)],T('mod_lilith_infernal_wheel').dps.damage_type) %$。",
	HERO_ROOM_LILITH_INFERNAL_WHEEL_NAME = "地狱之轮",
