	HERO_ROOM_LILITH_REAPERS_HARVEST_NAME = "收割",
	HERO_ROOM_LILITH_RESURRECTION_2_DESC = "莉莉丝拥有额外10%复活概率，该复活概率可由其躯体的透明度显明。透明度越高，复活概率越低。莉莉丝每次近战普攻可提升复活概率1%，每次远程普攻可提升复活概率1.5%。收割未触发秒杀时，提升复活概率1%，反之提升2%。每1%额外复活概率可加快神圣混沌的冷却0.15%、地狱之轮的冷却0.4%，并使收割秒杀的触发概率提升0.2%，最高加快15%，40%冷却，提高20%秒杀概率。当莉莉丝复活时，其额外复活概率减半。",
	HERO_ROOM_LILITH_RESURRECTION_2_NAME = "降临",
