	HERO_ROOM_LYNN_CHARM_OF_UNLUCK_NAME = "厄运符印",
	HERO_ROOM_LYNN_DESPAIR_DESC = "%$ cooldown_str((((T('hero_lynn')).timed_attacks.list[1]).cooldown)) %$莉恩诅咒身边最多%$ (((T('hero_lynn')).hero.skills.despair).max_count[levels((T('hero_lynn')).hero.skills.despair)]) %$名敌人，使他们移速降低%$ (1 - ((T('hero_lynn')).hero.skills.despair).speed_factor[levels((T('hero_lynn')).hero.skills.despair)]) %$%，伤害降低至%$ (((T('hero_lynn')).hero.skills.despair).damage_factor[levels((T('hero_lynn')).hero.skills.despair)]) %$%，持续%$ (((T('hero_lynn')).hero.skills.despair).duration[levels((T('hero_lynn')).hero.skills.despair)]) %$秒。绝望诅咒会反向作用于莉恩。",
	HERO_ROOM_LYNN_DESPAIR_NAME = "绝望诅咒",
	HERO_ROOM_LYNN_HEXFURY_DESC = "%$ cooldown_str(((T('hero_lynn')).melee.attacks[3].cooldown)) %$莉恩连续斩击%$ ((((T('hero_lynn')).hero.skills.hexfury).loops[levels((T('hero_lynn')).hero.skills.hexfury)]) * #(T('hero_lynn')).melee.attacks[3].hit_times) %$次，每次造成%$ damage_str((T('hero_lynn')).melee.attacks[3].damage_min,(T('hero_lynn')).melee.attacks[3].damage_max,(T('hero_lynn')).melee.attacks[3].damage_type) %$。敌人身上每有厄运诅咒、绝望诅咒、虚弱诅咒、命运封印的一种，斩击伤害便提升%$ (((T('hero_lynn')).hero.skills.hexfury).extra_damage) %$点。该技能经验获取量与造成总伤相关。",
