	HERO_ROOM_LYNN_ULTIMATE_NAME = "命运封印",
	HERO_ROOM_LYNN_WEAKENING_DESC = "%$ cooldown_str((((T('hero_lynn')).timed_attacks.list[2]).cooldown)) %$若目前拦截的敌人护甲或法抗高于10，莉恩会诅咒身边最多%$ (((T('hero_lynn')).hero.skills.weakening).max_count[levels((T('hero_lynn')).hero.skills.weakening)]) %$名敌人，降低他们%$ (((T('hero_lynn')).hero.skills.weakening).armor_reduction[levels((T('hero_lynn')).hero.skills.weakening)]) %$%护甲与%$ (((T('hero_lynn')).hero.skills.weakening).magic_armor_reduction[levels((T('hero_lynn')).hero.skills.weakening)]) %$%法抗，并根据实际削减法抗值额外削减一半数值的物抗，持续%$ (((T('hero_lynn')).hero.skills.weakening).duration[levels((T('hero_lynn')).hero.skills.weakening)]) %$秒。虚弱诅咒会削弱一半并反向作用于莉恩。",
	HERO_ROOM_LYNN_WEAKENING_NAME = "虚弱诅咒",
	HERO_ROOM_MAGNUS_ARCANE_RAIN_DESC = "%$ cooldown_str(((T('hero_magnus')).timed_attacks.list[2].cooldown)) %$马格努斯召唤奥术风暴，在目标区域内降下%$ (((T('hero_magnus')).hero.skills.arcane_rain).count[(levels((T('hero_magnus')).hero.skills.arcane_rain))]) %$枚奥术雨滴，每枚雨滴对%$ ((T('magnus_arcane_rain')).damage_radius) %$范围内敌人造成%$ damage_str(((T('hero_magnus')).hero.skills.arcane_rain).damage[(levels((T('hero_magnus')).hero.skills.arcane_rain))],((T('hero_magnus')).hero.skills.arcane_rain).damage[(levels((T('hero_magnus')).hero.skills.arcane_rain))],(T('magnus_arcane_rain')).damage_type) %$。",
	HERO_ROOM_MAGNUS_ARCANE_RAIN_NAME = "奥术风暴",
	HERO_ROOM_MAGNUS_MIRAGE_2_DESC = "马格努斯的幻影分身会释放弱化的奥术风暴，每个幻影分身释放的奥术风暴拥有主英雄奥术风暴%$ ((E:get_template('soldier_magnus_illusion')).skill_radius_factor) %$%的作用范围，造成%$ ((E:get_template('soldier_magnus_illusion')).skill_damage_factor) %$%的魔法伤害。",
