	HERO_ROOM_MAGNUS_MIRAGE_NAME = "幻影",
	HERO_ROOM_MALIK_FISSURE_DESC = "%$ cooldown_str(((T('hero_malik')).melee.attacks[4].cooldown)) %$马利克高高跃起，锤击地面，引起数片地震，每片地震对%$ ((T('aura_malik_fissure')).aura.damage_radius) %$范围内敌人造成%$ damage_str(((T('hero_malik')).hero.skills.fissure).damage_min[(levels((T('hero_malik')).hero.skills.fissure))],((T('hero_malik')).hero.skills.fissure).damage_max[(levels((T('hero_malik')).hero.skills.fissure))],(T('aura_malik_fissure')).aura.damage_type) %$，并使其眩晕%$ ((T('mod_malik_stun')).modifier.duration) %$秒。在道路的交汇处，地震将额外向多条道路蔓延。",
	HERO_ROOM_MALIK_FISSURE_NAME = "地震",
	HERO_ROOM_MALIK_SMASH_DESC = "%$ cooldown_str(((T('hero_malik')).melee.attacks[3].cooldown)) %$马利克调动重锤之力，对面前%$ ((T('hero_malik')).melee.attacks[3].damage_radius) %$范围内敌人造成%$ damage_str(((T('hero_malik')).hero.skills.smash).damage_min[(levels((T('hero_malik')).hero.skills.smash))],((T('hero_malik')).hero.skills.smash).damage_max[(levels((T('hero_malik')).hero.skills.smash))],(T('hero_malik')).melee.attacks[3].damage_type) %$，并有%$ rate_str((((T('hero_malik')).hero.skills.smash).stun_chance[(levels((T('hero_malik')).hero.skills.smash))])) %$使其眩晕%$ ((T('mod_malik_stun')).modifier.duration) %$秒。该技能获取经验量和造成总伤相关。",
	HERO_ROOM_MALIK_SMASH_NAME = "粉碎重锤",
