	HERO_ROOM_MALIK_SURGE_OF_FLAME_NAME = "震慑",
	HERO_ROOM_MARGOSA_BAT_FAMILIAR_DESC = "召唤一只吸血蝙蝠伴她作战，每隔%$ (T('bat_reinforcement_special_dark_army').custom_attack.cooldown) %$秒攻击一次，每次造成%$ damage_str(((T('hero_margosa')).hero.skills.bat_familiar).damage_min_config[levels((T('hero_margosa')).hero.skills.bat_familiar)],((T('hero_margosa')).hero.skills.bat_familiar).damage_max_config[levels((T('hero_margosa')).hero.skills.bat_familiar)],T('bat_reinforcement_special_dark_army').custom_attack.damage_type) %$。",
