	HERO_ROOM_MARGOSA_DARK_CALL_NAME = "黑暗呼唤",
	HERO_ROOM_MARGOSA_MYST_FORM_DESC = "%$ cooldown_str(((T('hero_margosa')).timed_attacks.list[1].cooldown)) %$使自己被魔法迷雾环绕。迷雾中的敌人每%$ (T('mod_dmg_fog_hero_margosa').dps.damage_every) %$秒受到%$ damage_str(((T('hero_margosa')).hero.skills.myst_form).damage_config[levels((T('hero_margosa')).hero.skills.myst_form)],((T('hero_margosa')).hero.skills.myst_form).damage_config[levels((T('hero_margosa')).hero.skills.myst_form)],T('mod_dmg_fog_hero_margosa').dps.damage_type) %$，移动速度降低%$ (1 - T('mod_slow_fog_hero_margosa').slow.factor) %$%，并使敌人造成的伤害降低%$ (1 - ((T('hero_margosa')).hero.skills.myst_form).damage_factor[levels((T('hero_margosa')).hero.skills.myst_form)]) %$%，持续%$ (T('aura_fog_hero_margosa').aura.duration) %$秒。",
	HERO_ROOM_MARGOSA_MYST_FORM_NAME = "绝望迷雾",
	HERO_ROOM_MARGOSA_ULTIMATE_2_DESC = "%$ cooldown_str(((T('hero_margosa')).ultimate.cooldown)) %$当生命值耗尽或附近有敌人时，苦楝夫人变身为渴血的野兽，生命值恢复至全满，普通攻击变为真实伤害，伤害提升%$ (((T('hero_margosa')).ultimate.damage_factor) - 1) %$%，攻击速度与移动速度大幅提升，吸血效果强化，持续%$ (((T('hero_margosa')).hero.skills.ultimate).duration[levels((T('hero_margosa')).hero.skills.ultimate)]) %$秒。变身期间使用绝望迷雾或黑暗呼唤将提前退出野兽形态。",
	HERO_ROOM_MARGOSA_ULTIMATE_2_NAME = "野兽形态",
	HERO_ROOM_MARGOSA_ULTIMATE_DESC = "苦楝夫人免疫剧毒，普通攻击造成残暴伤害。远距离调遣时，苦楝夫人化身蝙蝠高速飞行。",
	HERO_ROOM_MARGOSA_ULTIMATE_NAME = "嗜血本能",
