	HERO_ROOM_MARGOSA_VAMPIRIC_TOUCH_NAME = "吸血鬼之触",
	HERO_ROOM_MECHA_GOBLIDRONES_DESC = "%$ cooldown_str((((T('hero_mecha')).hero.skills.goblidrones).cooldown[levels((T('hero_mecha')).hero.skills.goblidrones)])) %$召唤%$ 2 %$架无人机攻击敌人，持续%$ (table.tail({8, 10, 12})) %$秒，每次攻击造成%$ damage_str(table.tail({4, 7, 10}),table.tail({5, 10, 15}),64) %$。",
