	HERO_ROOM_MECHA_MINE_DROP_DESC = "%$ cooldown_str((((T('hero_mecha')).hero.skills.mine_drop).cooldown[levels((T('hero_mecha')).hero.skills.mine_drop)])) %$静止时，机甲定期在路径上安放至多%$ (table.tail({2, 3, 4})) %$枚爆炸地雷，爆炸造成%$ damage_str(table.tail({16, 24, 32}),table.tail({26, 38, 50}),8) %$。",
