	HERO_ROOM_MINOTAUR_DAEDALUSMAZE_NAME = "代达罗斯的迷宫",
	HERO_ROOM_MINOTAUR_DOOMSPIN_DESC = "%$ cooldown_str(((T('hero_minotaur')).timed_attacks.list[1].cooldown)) %$卡兹对%$ ((T('hero_minotaur')).timed_attacks.list[1].damage_radius) %$范围内敌人造成%$ damage_str(((T('hero_minotaur')).hero.skills.doomspin).damage_min[(levels((T('hero_minotaur')).hero.skills.doomspin))],((T('hero_minotaur')).hero.skills.doomspin).damage_max[(levels((T('hero_minotaur')).hero.skills.doomspin))],(T('hero_minotaur')).timed_attacks.list[1].damage_type) %$并恢复造成伤害总量25%的生命值。",
