	HERO_ROOM_VAMPIRESS_SLAYER_2_NAME = "杀戮生长",
	HERO_ROOM_VAMPIRESS_SLAYER_3_DESC = "卢克蕾齐娅免疫毒素，每次普攻恢复3点生命值，且被视为亡灵单位。远距离移动时，卢克蕾齐娅变身蝙蝠飞行，提升自身%$ (T('hero_vampiress')).motion.max_speed_bat - (T('hero_vampiress')).motion.max_speed %$点移速。",
	HERO_ROOM_VAMPIRESS_SLAYER_3_NAME = "鲜血后裔",
