	HERO_ROOM_VAMPIRESS_SLAYER_NAME = "绛红之舞",
	HERO_ROOM_VAMPIRESS_VAMPIRISM_DESC = "%$ cooldown_str((((T('hero_vampiress')).melee.attacks[2]).cooldown)) %$卢克蕾齐娅汲取敌人的生命，造成%$ damage_str(((T('hero_vampiress')).hero.skills.vampirism).damage[levels((T('hero_vampiress')).hero.skills.vampirism)],((T('hero_vampiress')).hero.skills.vampirism).damage[levels((T('hero_vampiress')).hero.skills.vampirism)],((T('hero_vampiress')).melee.attacks[2]).damage_type) %$并恢复等量生命值。被汲取的敌人流血%$ ((E:get_template('mod_vampiress_blood')).modifier.duration) %$秒，每%$ ((E:get_template('mod_vampiress_blood')).dps.damage_every) %$秒受到%$ damage_str((E:get_template('mod_vampiress_blood')).dps.damage_min + (levels((T('hero_vampiress')).hero.skills.vampirism)) * (E:get_template('mod_vampiress_blood')).dps.damage_inc,(E:get_template('mod_vampiress_blood')).dps.damage_min + (levels((T('hero_vampiress')).hero.skills.vampirism)) * (E:get_template('mod_vampiress_blood')).dps.damage_inc,(E:get_template('mod_vampiress_blood')).dps.damage_type) %$。",
	HERO_ROOM_VAMPIRESS_VAMPIRISM_NAME = "生命汲取",
