	HERO_ROOM_VAN_HELSING_BEACONOFLIGHT_NAME = "光明信标",
	HERO_ROOM_VAN_HELSING_HOLYGRENADE_DESC = "%$ cooldown_str(((T('hero_van_helsing')).timed_attacks.list[3].cooldown)) %$但丁对可沉默单位投掷一枚圣水炸弹，在%$ (E:get_template('van_helsing_grenade').bullet.damage_radius) %$范围内造成沉默效果，持续%$ (((T('hero_van_helsing')).hero.skills.holygrenade).silence_duration[levels((T('hero_van_helsing')).hero.skills.holygrenade)]) %$秒。",
	HERO_ROOM_VAN_HELSING_HOLYGRENADE_NAME = "圣水炸弹",
	HERO_ROOM_VAN_HELSING_MULTISHOOT_DESC = "%$ cooldown_str(((T('hero_van_helsing')).timed_attacks.list[1].cooldown)) %$但丁使用手枪连射%$ (((T('hero_van_helsing')).hero.skills.multishoot).loops[(levels((T('hero_van_helsing')).hero.skills.multishoot))]) %$发，每发造成%$ damage_str(E:get_template('van_helsing_shotgun').bullet.damage_min,E:get_template('van_helsing_shotgun').bullet.damage_max,E:get_template('van_helsing_shotgun').bullet.damage_type) %$。射击目标死亡后，就近转火。",
	HERO_ROOM_VAN_HELSING_MULTISHOOT_NAME = "致命连射",
	HERO_ROOM_VAN_HELSING_RELICOFPOWER_DESC = "%$ cooldown_str(((T('hero_van_helsing')).melee.attacks[2].cooldown)) %$但丁对面前敌人使用遗迹之力，削减他%$ (((T('hero_van_helsing')).hero.skills.relicofpower).armor_reduce_factor[levels((T('hero_van_helsing')).hero.skills.relicofpower)]) %$%的双抗。该技能只会对生命高于500，且护甲/法抗高于0的敌人使用。",
	HERO_ROOM_VAN_HELSING_RELICOFPOWER_NAME = "遗迹之力",
