	HERO_ROOM_VAN_HELSING_SILVERBULLET_NAME = "纯银子弹",
	HERO_ROOM_VENOM_BERSERKER_2_DESC = "%$ cooldown_str((table.tail({35, 35, 35}))) %$当格里姆森生命值低于%$ 0.5 %$%时自动触发，完全变身持续%$ (10) %$秒。变身期间攻击伤害提升%$ ( (table.tail({1.25, 1.5, 1.75}) * 100 - 100) ) / 100 %$%，每次攻击恢复总生命值的%$ 0.1 %$%。变身状态下，重塑血肉的触发阈值提升50%，并在重塑血肉触发时退出野性变身，返还50%冷却。变身期间恢复的生命可将格里姆森拉回死亡状态。",
	HERO_ROOM_VENOM_BERSERKER_2_NAME = "原始野性",
