	HERO_ROOM_VOODOO_WITCH_DEATHSKULL_NAME = "亡骨献祭",
	HERO_ROOM_VOODOO_WITCH_LAUGHINGSKULLS_DESC = "冷笑骷髅每隔%$ ((E:get_template('voodoo_witch_skull')).ranged.attacks[1].cooldown) %$秒攻击一名敌人，造成%$ damage_str(((T('bolt_voodoo_witch_skull')).bullet.damage_min) + sum(((T('hero_voodoo_witch')).hero.skills.laughingskulls).extra_damage),((T('bolt_voodoo_witch_skull')).bullet.damage_max) + sum(((T('hero_voodoo_witch')).hero.skills.laughingskulls).extra_damage),(T('bolt_voodoo_witch_skull')).bullet.damage_type) %$，最多攻击%$ ((E:get_template('voodoo_witch_skull')).max_shots) %$次。",
