	HERO_ROOM_WILBUR_MISSILE_NAME = "导弹",
	HERO_ROOM_WILBUR_SMOKE_DESC = "%$ cooldown_str((((T('hero_wilbur')).timed_attacks.list[1]).cooldown)) %$威尔伯在身下制造持续%$ (((T('hero_wilbur')).hero.skills.smoke).duration[levels((T('hero_wilbur')).hero.skills.smoke)]) %$秒的迷雾，使%$ ((T('aura_smoke_wilbur')).aura.radius) %$范围内敌人移速x%$ (((T('hero_wilbur')).hero.skills.smoke).slow_factor[levels((T('hero_wilbur')).hero.skills.smoke)]) %$%。",
	HERO_ROOM_WILBUR_SMOKE_NAME = "迷雾",
	HERO_ROOM_WILBUR_ULTIMATE_DESC = "%$ cooldown_str(((T('hero_wilbur')).ultimate.cooldown)) %$威尔伯召唤%$ (#(T('hero_wilbur_ultimate')).spawn_offsets) %$架无人机协助战斗，驻场%$ ((T('drone_wilbur')).duration) %$秒。无人机全图索敌，每隔%$ ((T('drone_wilbur')).custom_attack.cooldown) %$秒攻击一次，最多攻击%$ ((T('drone_wilbur')).custom_attack.max_shots) %$次，每次造成%$ damage_str(((T('hero_wilbur')).hero.skills.ultimate).damage[levels((T('hero_wilbur')).hero.skills.ultimate)],((T('hero_wilbur')).hero.skills.ultimate).damage[levels((T('hero_wilbur')).hero.skills.ultimate)],(T('drone_wilbur')).custom_attack.damage_type) %$。",
	HERO_ROOM_WILBUR_ULTIMATE_NAME = "无人机蜂群",
	HERO_ROOM_WITCH_BERSERKER_2_DESC = "%$ cooldown_str((table.tail({12, 12, 12}))) %$斯特蕾吉拦截敌人时向后传送，减少所有其它技能冷却2秒，并在原地留下一个诱饵。诱饵拥有%$ (table.tail({65, 97, 130})) %$点生命值，被摧毁时爆炸，眩晕周围敌人%$ (table.tail({2, 2.5, 3})) %$秒。",
	HERO_ROOM_WITCH_BERSERKER_2_NAME = "闪光诱饵",
	HERO_ROOM_WITCH_BERSERKER_3_DESC = "%$ cooldown_str((table.tail({17.5, 17.5, 17.5}))) %$斯特蕾吉召唤%$ (table.tail({2, 3, 4})) %$只黑猫与敌人作战，持续%$ (8) %$秒。每只黑猫拥有%$ hp_str(table.tail({60, 85, 110})) %$，每次攻击造成%$ damage_str(table.tail({2, 5, 7}),table.tail({3, 7, 11}),2) %$。",
	HERO_ROOM_WITCH_BERSERKER_3_NAME = "黑夜煞星",
	HERO_ROOM_WITCH_BERSERKER_4_DESC = "%$ cooldown_str((table.tail({16, 16, 16}))) %$斯特蕾吉向路径上投掷一大瓶魔药，造成%$ damage_str(table.tail({65, 104, 156}),table.tail({65, 104, 156}),32) %$，并使范围内敌人移速x%$ 0.5 %$%，持续%$ (table.tail({5, 6, 8})) %$秒。",
	HERO_ROOM_WITCH_BERSERKER_4_NAME = "粘稠魔药",
	HERO_ROOM_WITCH_BERSERKER_5_DESC = "%$ cooldown_str((table.tail({27, 27, 27, 27}))) %$斯特蕾吉将%$ (100) %$范围内最多%$ (table.tail({4, 6, 8, 10})) %$名敌人沿路径往回传送%$ (20) %$个节点，并使其昏睡%$ (table.tail({3, 4, 5, 6})) %$秒。",
	HERO_ROOM_WITCH_BERSERKER_5_NAME = "昏昏欲退",
	HERO_ROOM_WITCH_BERSERKER_DESC = "%$ cooldown_str((table.tail({20, 20, 20}))) %$斯特蕾吉将一名生命值低于%$ (table.tail({1000, 2000, 3000})) %$的敌人变成南瓜，持续%$ (table.tail({8, 8, 8})) %$秒。南瓜继承敌人%$ (table.tail({0.7, 0.55, 0.4})) %$%的生命值，双抗清零，移速为%$ (20) %$。",
	HERO_ROOM_WITCH_BERSERKER_NAME = "南瓜魔术",
	HERO_ROOM_WIZARD_ARCANETORRENT_DESC = "年迈的法师热衷于在后辈前展示力量。场上每多一座法师塔，纽维斯的伤害就提升%$ (((T('hero_wizard')).hero.skills.arcanetorrent).factor[(levels((T('hero_wizard')).hero.skills.arcanetorrent))]) %$%。该伤害提升对魔法飞弹、分解同样生效。",
	HERO_ROOM_WIZARD_ARCANETORRENT_NAME = "法术洪流",
	HERO_ROOM_WIZARD_CHAINSPELL_DESC = "%$ cooldown_str(((T('hero_wizard')).ranged.attacks[2].cooldown)) %$纽维斯的普攻额外进行%$ (((T('hero_wizard')).hero.skills.chainspell).bounces[(levels((T('hero_wizard')).hero.skills.chainspell))]) %$次弹射。",
	HERO_ROOM_WIZARD_CHAINSPELL_NAME = "连锁反应",
	HERO_ROOM_WIZARD_DISINTEGRATE_DESC = "%$ cooldown_str(((T('hero_wizard')).timed_attacks.list[1].cooldown)) %$纽维斯用知识的力量分解最多%$ (((T('hero_wizard')).hero.skills.disintegrate).count[(levels((T('hero_wizard')).hero.skills.disintegrate))]) %$名血量总和不超过%$ (((T('hero_wizard')).hero.skills.disintegrate).total_damage[(levels((T('hero_wizard')).hero.skills.disintegrate))]) %$的敌人。",
	HERO_ROOM_WIZARD_DISINTEGRATE_NAME = "分解",
	HERO_ROOM_WIZARD_MAGICMISSILE_DESC = "%$ cooldown_str(((T('hero_wizard')).timed_attacks.list[2].cooldown)) %$纽维斯发射%$ (((T('hero_wizard')).hero.skills.magicmissile).count[(levels((T('hero_wizard')).hero.skills.magicmissile))]) %$枚魔法飞弹，全图范围内追踪敌人，每枚飞弹造成%$ damage_str(((T('hero_wizard')).hero.skills.magicmissile).damage[(levels((T('hero_wizard')).hero.skills.magicmissile))],((T('hero_wizard')).hero.skills.magicmissile).damage[(levels((T('hero_wizard')).hero.skills.magicmissile))],(T('missile_wizard')).bullet.damage_type) %$。",
	HERO_ROOM_WIZARD_MAGICMISSILE_NAME = "魔法飞弹",
	HERO_ROOM_WUKONG_BERSERKER_2_DESC = "%$ cooldown_str((table.tail({24, 22, 20}))) %$孙悟空变出2只毛猴并肩作战，各拥有%$ hp_str(table.tail({104, 130, 156})) %$，驻场%$ (table.tail({9, 9, 9})) %$秒，每次攻击造成%$ damage_str(table.tail({4, 8, 12}),table.tail({5, 10, 15}),2) %$。",
	HERO_ROOM_WUKONG_BERSERKER_2_NAME = "身外身法",
	HERO_ROOM_WUKONG_BERSERKER_3_DESC = "%$ cooldown_str((table.tail({17, 17, 17}))) %$孙悟空将金箍棒掷向空中，变出%$ (table.tail({3, 5, 7})) %$根落向敌人，每根对%$ (50) %$范围内敌人造成%$ damage_str(table.tail({13, 18, 23}),table.tail({19, 32, 39}),2) %$，并眩晕%$ (3) %$秒。",
	HERO_ROOM_WUKONG_BERSERKER_3_NAME = "雨落千钧",
	HERO_ROOM_WUKONG_BERSERKER_4_DESC = "%$ cooldown_str((table.tail({50.5, 47.5, 44}))) %$孙悟空将金箍棒变为参天大小，重压一名敌人将其秒杀，并对%$ (90) %$范围内敌人造成%$ damage_str(table.tail({120, 160, 200}),table.tail({140, 200, 260}),1) %$。",
	HERO_ROOM_WUKONG_BERSERKER_4_NAME = "神珍定海",
	HERO_ROOM_WUKONG_BERSERKER_5_DESC = "%$ cooldown_str((table.tail({42, 42, 42, 42}))) %$小白龙从天而降，造成共计%$ damage_str(table.tail({260, 390, 520, 650}),table.tail({260, 390, 520, 650}),1) %$，并在落点留下减速区域，使敌人移速x%$ table.tail({0.5, 0.5, 0.5, 0.5}) %$%，持续%$ (table.tail({3, 3.5, 4, 4.5})) %$秒。释放本技能时，悟空恢复全部生命值。",
	HERO_ROOM_WUKONG_BERSERKER_5_NAME = "白龙腾渊",
	HERO_ROOM_WUKONG_BERSERKER_DESC = "猪八戒永远跟随孙悟空征战。八戒拥有%$ hp_str(table.tail({78, 117, 182})) %$，每次攻击造成%$ damage_str(table.tail({3, 5, 10}),table.tail({4, 7, 15}),2) %$，并有%$ table.tail({0.3, 0.4, 0.5}) %$%概率对%$ (72) %$范围内敌人造成%$ (table.tail({39, 71, 97})) %$-%$ (table.tail({45, 91, 117})) %$点物理伤害。",
	HERO_ROOM_WUKONG_BERSERKER_NAME = "八戒师弟",
	HERO_ROOM_XIN_DARING_STRIKE_DESC = "%$ cooldown_str((((T('hero_xin')).timed_attacks.list[1]).cooldown)) %$鑫进入无敌状态，闪现至生命值最高的敌人身前并英勇地打击他，造成%$ damage_str(((T('hero_xin')).hero.skills.daring_strike).damage_min[levels((T('hero_xin')).hero.skills.daring_strike)],((T('hero_xin')).hero.skills.daring_strike).damage_max[levels((T('hero_xin')).hero.skills.daring_strike)],((T('hero_xin')).timed_attacks.list[1]).damage_type) %$。鑫可瞬移至任何位置，并在原地留下分身短暂代为拦截敌人。",
	HERO_ROOM_XIN_DARING_STRIKE_NAME = "英勇打击",
	HERO_ROOM_XIN_INSPIRE_DESC = "%$ cooldown_str((((T('hero_xin')).timed_attacks.list[2]).cooldown)) %$鑫短暂无敌，怒喝一声，使周围友军的伤害x%$ ((E:get_template('mod_xin_inspire')).inflicted_damage_factor) %$，持续%$ (((T('hero_xin')).hero.skills.inspire).duration[levels((T('hero_xin')).hero.skills.inspire)]) %$秒。",
	HERO_ROOM_XIN_INSPIRE_NAME = "激励怒吼",
	HERO_ROOM_XIN_MIND_OVER_BODY_DESC = "%$ cooldown_str((((T('hero_xin')).timed_attacks.list[3]).cooldown)) %$当鑫的剩余生命值低于%$ (((T('hero_xin')).timed_attacks.list[3]).min_health_factor) %$%时，鑫会喝下熊猫特酿，进入驭体于灵状态，持续%$ (((T('hero_xin')).hero.skills.mind_over_body).duration[levels((T('hero_xin')).hero.skills.mind_over_body)]) %$秒。驭体于灵状态下，鑫的伤害提升%$ (((T('hero_xin')).hero.skills.mind_over_body).damage_buff[levels((T('hero_xin')).hero.skills.mind_over_body)]) %$点，并每%$ (((T('hero_xin')).hero.skills.mind_over_body).heal_every[levels((T('hero_xin')).hero.skills.mind_over_body)]) %$秒恢复%$ (((T('hero_xin')).hero.skills.mind_over_body).heal_hp[levels((T('hero_xin')).hero.skills.mind_over_body)]) %$点生命，且会快速驱散中毒、晕眩、流血等异常效果。退出驭体于灵状态时，熊猫流派、英勇打击、激励怒吼的冷却时间均会减少10%。驭体于灵状态下时，每次普攻有50%概率加快熊猫流派、英勇打击、激励怒吼冷却10%。任何时候，鑫普攻均有50%概率加快驭体于灵冷却10%。",
	HERO_ROOM_XIN_MIND_OVER_BODY_NAME = "驭体于灵",
	HERO_ROOM_XIN_PANDA_STYLE_DESC = "%$ cooldown_str((((T('hero_xin')).melee.attacks[3]).cooldown)) %$ 鑫施展熊猫流派（屁股墩），对%$ (((T('hero_xin')).melee.attacks[3]).damage_radius) %$范围内敌人造成%$ damage_str(((T('hero_xin')).hero.skills.panda_style).damage_min[levels((T('hero_xin')).hero.skills.panda_style)],((T('hero_xin')).hero.skills.panda_style).damage_max[levels((T('hero_xin')).hero.skills.panda_style)],((T('hero_xin')).melee.attacks[3]).damage_type) %$。",
	HERO_ROOM_XIN_PANDA_STYLE_NAME = "熊猫流派",
	HERO_ROOM_XIN_ULTIMATE_DESC = "%$ cooldown_str(((T('hero_xin')).ultimate.cooldown)) %$鑫召唤%$ (((T('hero_xin')).hero.skills.ultimate).count[levels((T('hero_xin')).hero.skills.ultimate)]) %$名弟子支援，每名弟子肘敌人%$ ((E:get_template('soldier_xin_ultimate')).max_attack_count) %$下后退场，每肘造成%$ damage_str(((T('hero_xin')).hero.skills.ultimate).damage[levels((T('hero_xin')).hero.skills.ultimate)],((T('hero_xin')).hero.skills.ultimate).damage[levels((T('hero_xin')).hero.skills.ultimate)],(E:get_template('soldier_xin_ultimate')).melee.attacks[1].damage_type) %$。",
	HERO_ROOM_XIN_ULTIMATE_NAME = "熊猫乱舞",
	HERO_SPACE_ELF_DESCRIPTION = "“要想了解黑暗，必先踏入黑暗。”多年来，虚空法师赛莉恩因涉足未知的异世界力量而被同伴们排斥。尽管如此，她始终克制地使用着自己的力量，随时准备在需要时出手。",
	HERO_SPACE_ELF_NAME = "赛莉恩",
	HERO_SPACE_ELF_SPECIAL = "星界镜像，虚空裂隙，黑曜庇护，空间扭曲，异域囚笼",
	HERO_SPIDER_DESCRIPTION = "丝派蒂尔隶属暮光精灵的一支猎蛛部队，任务是歼灭蜘蛛女王和其手下的邪教，如今她是最后一名队员。她将暗影魔法与独一无二狩猎技巧结合，成为令整片大陆都闻风丧胆致命刺客。",
	HERO_SPIDER_NAME = "丝派蒂尔",
	HERO_SPIDER_SPECIAL = "暗杀，蛛网缠绕，地道穿越，猎手本能，蛛后降临",
	HERO_STEAMFRIGATE_NAME = "黑海盗",
	HERO_STEAM_FRIGATE_NAME = "黑海盗",
	HERO_TANK_DESCRIPTION = "经历了无数年的研发，一代又一代的原型都以毁灭告终。最终就只剩下这一辆毁灭坦克。没有任何军队胆敢直面这样一位灾星。",
	HERO_TANK_EXPENDABLES_NAME = "敢死队",
	HERO_TANK_NAME = "毁灭坦克 SG-11",
	HERO_TANK_SPECIAL = "多刺蛞蝓，炽热导弹，猛击地，敢死队，灼热大炮，女武神的呼唤",
	HERO_THOR_DESCRIPTION = "这位身材高大的半神， 肉身由雷电构成， 挥舞着一把附有雷电之力的战锤。他是风暴之神的儿子， 也是迪纳斯国王的挚友。",
	HERO_THOR_NAME = "索尔",
	HERO_THOR_SPECIAL = "雷神之锤， 雷霆一击， 雷电中继",
	HERO_TRAMIN_DESCRIPTION = "头脑机敏绝伦的特拉敏，曾是好战分子们那些绝妙发明背后的主创，现在俨然已经成为维兹南的部队中最不可或缺的核心人物之一。充裕的研究经费让他得以肆意发挥自己的天赋，而他的成果也完全对得起这笔投入。",
	HERO_TRAMIN_NAME = "特拉敏大师",
	HERO_TRAMIN_SPECIAL = "自爆机器人，饮硝狂奔，闪光弹，火箭弹幕，疯狂炸弹人，火箭跳",
	HERO_VAMPIRESS_DESCRIPTION = "实力强劲的红发吸血鬼，曾经是血族王子瓦西里的女儿，现在则是猎魔人但丁的恋人。",
	HERO_VAMPIRESS_NAME = "卢克雷齐娅",
	HERO_VAMPIRESS_SPECIAL = "生命汲取，绛红之舞，杀戮生长，鲜血后裔",
	HERO_VAN_HELSING_DESCRIPTION = "独来独往，不苟言笑的猎魔人。不论生死，他都是我们的光明信标，为了心中的正义战斗不息，永不言弃。",
	HERO_VAN_HELSING_NAME = "但丁",
	HERO_VAN_HELSING_SPECIAL = "纯银子弹，致命连射，遗迹之力，圣水炸弹，光明信标",
	HERO_VENOM_DESCRIPTION = "邪教徒没能把佣兵格里姆森变成恶煞，便将他囚禁起来，任其腐烂。这段痛苦的经历意外赐予了格里姆森变形的能力(和深不可测的胃袋)，他利用这份力量逃出了邪教的控制，并发誓有朝一日必将归来，完成复仇。",
	HERO_VENOM_NAME = "格里姆森",
	HERO_VENOM_SPECIAL = "贯心追猎，原始野性，致命尖刺，重塑血肉，死亡蔓延",
	HERO_VESPER_DESCRIPTION = "维斯珀精通剑术与箭法，凭此胜任利尼维亚军队指挥官的职位。在利尼维亚沦陷、迪纳斯国王失踪之后，他集结了所有能够召集的部队，开始了一场旨在迎回前任统治者的征途。",
	HERO_VESPER_NAME = "维斯珀",
	HERO_VESPER_SPECIAL = "穿膝利箭，弹射箭矢，金蝉脱壳，武艺绽放，箭矢风暴",
	HERO_VEZNAN_DESCRIPTION = "传奇一般的法师，也是迪纳斯的挚友。早年寻求奥术的力量，之后则修行黑魔法，与恶魔签订契约。力量就是权力！",
	HERO_VEZNAN_NAME = "维兹南",
	HERO_VEZNAN_SPECIAL = "灵魂裂解，苦痛牢笼，奥术新星，恶魔契约",
	HERO_VOODOO_WITCH_DESCRIPTION = "娴熟运用超自然力量的土克亚部族女巫，能将敌人的灵魂封印在骷髅里，成为她力量的源泉",
	HERO_VOODOO_WITCH_NAME = "女巫",
	HERO_VOODOO_WITCH_SPECIAL = "冷笑骷髅，亡骨献祭，骨骸舞蹈，恐惧光环，巫毒魔法",
	HERO_WILBUR_DESCRIPTION = "可敬的冒险家！天才的发明家！威尔伯将是我们天空中的眼睛！",
	HERO_WILBUR_NAME = "威尔伯",
	HERO_WILBUR_SPECIAL = "迷雾，导弹，自走炸弹，无人机蜂群",
	HERO_WITCH_DESCRIPTION = "斯特蕾吉总喜欢变些不伤人的有趣戏法，给路过仙境森林的人吓一跳。但谁若是威胁到了森林和她的侏儒同胞，立马就会明白平日她顽皮的笑脸只是表象，这位女巫一旦认真起来绝不善罢甘休。",
	HERO_WITCH_NAME = "斯特蕾吉",
	HERO_WITCH_SPECIAL = "南瓜魔术，闪光诱饵，黑夜煞星，粘稠魔药，昏昏欲退",
	HERO_WIZARD_DESCRIPTION = "学识渊博、值得尊敬的老法师，维兹南的师父。虽然年纪已大，但他仍然是个强大的法师。据说在越多的后生面前，他能表现出越强的实力。",
