	LAST_HOOK_TARGET_NOT_INITIALIZED = "！如果看见这条消息，请截下来发给作者 target: %s, mod: %s",
	LEGAL_GOV_APPROVAL = "文化部备案：文网游进字〔2018〕0058号%s",
	LEGAL_HEALTH_ADVICE = "健康忠告：抵制不良游戏，拒绝盗版游戏。注意自我保护，谨防受骗上当。适度游戏益脑，沉迷游戏伤身。合理安排时间，享受健康生活。",
	LEVEL_1000_HISTORY = "注二号路径为下面的直线",
	LEVEL_1000_TITLE = "斗蛐蛐专用关卡1",
	LEVEL_101_HISTORY = "数月以来，我们在南方森林中搜寻，却始终没能成功找到迪纳斯国王的踪迹。这期间，我们与自然之灵——树灵结为了朋友，并遇到了他们不太友善的邻居——野兽族，它们一见到我们就不断袭击。\n我们必须尽快结束这场战斗，好继续寻找国王。",
	LEVEL_101_TITLE = "树之海洋",
	LEVEL_102_HISTORY = "保持警惕，消息通过仙灵传到了我们这里！森林之心正遭受攻击！我们必须回去帮助树灵。一些黑暗大军的部队会与我们一起加入战场，要时刻保持警惕。目前我们可能同舟共济，但情况随时可能发生改变。",
	LEVEL_102_TITLE = "守卫之门",
	LEVEL_103_HISTORY = "我们及时赶回了森林之心，但野兽族已经突破防线。打起精神，加固阵地！不惜一切代价保护森林之心，否则森林和树灵族必将遭遇灭顶之灾。",
	LEVEL_103_TITLE = "森林之心",
	LEVEL_104_HISTORY = "目前森林之心已经安全了，我们必须重新集结，乘胜追击。是时候将战线推向野兽族的领地了。带领部队登上森林的树梢，从制高点寻找它们的营地。",
	LEVEL_104_TITLE = "翡翠树梢",
	LEVEL_105_HISTORY = "多亏你占领了制高点，我们才在森林之外的某个古老遗迹中找到了野兽族的营地。请率领部队朝它们的领地进发，同时要警惕它们的埋伏。虽然我们又赢得了一场战斗，但这还远远没有结束。",
	LEVEL_105_TITLE = "荒废郊区",
	LEVEL_106_HISTORY = "我们或许在对抗野兽族时占了上风，但仍需面对它们的领袖——血辗。这位自封的野兽之王是个强大的对手，所以不要被他的蠢样所迷惑，否则你将命丧在它的獠牙之下。",
	LEVEL_106_TITLE = "野兽巢穴",
	LEVEL_107_HISTORY = "阻止野兽族夷平永辉森林后，我们追踪在背后推波助澜的复明教徒，来到一片荒凉之地。我们怀疑这就是他们实施邪恶计划的据点。敌在暗，我在明，必须小心为上……他们似乎有一些不为人知的本事。",
	LEVEL_107_TITLE = "冷峻山谷",
	LEVEL_108_HISTORY = "我们在深入邪教领地时，发现了一系列巨大洞穴，里面充满了与诡异魔法产生共鸣的水晶。复明教会正在开采这些水晶，这无疑是为了充当能量来源。至于目的何在，我们尚不清楚，但干扰开采活动一定能有效地打乱他们的阵脚。",
	LEVEL_108_TITLE = "绯红矿坑",
	LEVEL_109_HISTORY = "这些坑道曲折蜿蜒，令人晕头转向，但我们确信走对了路，因为复明教会的活动愈发频繁。随着我们逐渐深入，各种恐怖景象映入眼帘，这不禁让人怀疑邪教内部的癫狂程度究竟有多深。",
	LEVEL_109_TITLE = "邪恶路口",
	LEVEL_10_HEROIC = "英雄模式描述10",
	LEVEL_10_HISTORY = "我们已经抵达可怕的瓦拉杜勒国度。在这片贫瘠凄凉的大地上，死去的悲惨灵魂无法得到安息。\n\n祈求神明，别让兄弟们的灵魂困在这个地方...",
	LEVEL_10_IRON = "钢铁模式描述10",
	LEVEL_10_IRON_UNLOCK = "无火炮",
	LEVEL_10_MODES_UPGRADES = "等级4最高",
	LEVEL_10_TITLE = "废弃之地",
	LEVEL_110_HISTORY = "原来复明教会利用开采的水晶，在峡谷外建造了一个外观诡异的法器。它嗡嗡作响，充满怪异的能量，连周围的空气都显得格外沉重。在我们继续深入之前绝不能留此祸害。",
	LEVEL_110_TITLE = "神庙庭院",
	LEVEL_111_HISTORY = "我们终于走出了峡谷，但前路依旧漫长。现在，我们站在一个嵌满水晶的巨型传送门前，泛视先知魔蒂娅丝已经完成了她的仪式。接下来要面临什么，我们无从知晓，但我们依旧严阵以待。全体戒备！",
	LEVEL_111_TITLE = "峡谷高原",
	LEVEL_112_HISTORY = "我们迎回了迪纳斯国王，并一起穿过传送门踏入未知世界。这个奇异的世界看起来像是利尼维亚的扭曲倒影，但却是满目疮痍。小心脚下，潜伏在黑暗中的东西可比复明教会还要可怕。",
	LEVEL_112_TITLE = "枯萎农田",
	LEVEL_113_HISTORY = "熟悉的暴云寺院的轮廓隐约出现在地平线上。该去的方向非常明确，跟随那股愈发浓重的恶臭与异变前行，我们将找到这一切的源头。我们唯一要做的是在这片不断涌现骇人怪物的土地上幸存下来。",
	LEVEL_113_TITLE = "亵渎神庙",
	LEVEL_114_HISTORY = "这些该死的生物不知是从哪冒出来的！大部队已经身心俱疲，我们触碰到的一切都仿佛有生命，随时准备向我们发动攻击，似乎这整片土地都在尽全力与我们为敌。泛视先知魔蒂娅丝及其爪牙必定就在附近。",
	LEVEL_114_TITLE = "腐化山谷",
	LEVEL_115_HISTORY = "我们成功走出了山谷，现在唯一阻挡在我们与全视之魔眼之间的，就只剩下魔蒂娅丝了。早在山谷中我们就见识过她的能力，但在这里，她拥有自己主人的注视与庇护，势必占据更大的优势。尽管如此，我们仍不会被逆境所阻。振作起来！",
	LEVEL_115_TITLE = "恶视魔塔",
	LEVEL_116_HISTORY = "魔蒂娅丝已不复存在，但更强大的敌人全视之魔眼还在等着我们。这是彻底终结邪教与侵略的最后机会。如果我们不能团结到最后一刻，接下来不管事态如何发展都将毫无意义。开始决战吧！（英雄、钢铁暂未制作，请勿游玩）",
	LEVEL_116_TITLE = "欲念之巅",
	LEVEL_117_HISTORY = "曾经古灵精怪的仙境森林如今充满了不怀好意又毛骨悚然的气息。有消息称成群结队的活尸精灵战士和亡魂正在这片土地游荡，攻击旅人，腐化森林。将军，我们必须深入调查。",
	LEVEL_117_TITLE = "迷雾废墟",
	LEVEL_118_HISTORY = "深叶哨站传来消息，精灵们快要无法抵御活尸大军的攻势了。我们必须赶快前去支援精灵部队和他们队长——艾利丹，以免为时已晚。等到保住了哨站之后，我们就可以继续前进，直至这场入侵的根源所在。",
	LEVEL_118_TITLE = "深叶哨所",
	LEVEL_119_HISTORY = "艾利丹已经战至精疲力竭，他指引我们前往堕落神庙，一位号称灵魂掌控者·汎里埃的法师唤醒了活尸大军，企图指挥他们荡平大陆。我们必须不惜一切代价阻止他！",
	LEVEL_119_TITLE = "堕落神庙",
	LEVEL_11_HEROIC = "英雄模式描述11",
	LEVEL_11_HISTORY = "穿越凄凉山谷可不容易！我们已经接近旅途的终点，虽然我们人困马乏，但心中仍然充满崇高的目标。\n\n不过要小心...这里到处都是岩石与火焰泰坦...最好别惊扰到他们！",
	LEVEL_11_IRON = "钢铁模式描述11",
	LEVEL_11_IRON_UNLOCK = "无火炮\n无弓箭塔",
	LEVEL_11_MODES_UPGRADES = "最高5级",
	LEVEL_11_TITLE = "凄凉山谷",
	LEVEL_120_HISTORY = "我们收到了森林边界树灵族的紧急求救，他们正在遭受鳄鱼族的无情袭击，撑不了多久了。请务必要小心，将军。鳄鱼族肚子里可有很多的阴谋诡计。",
	LEVEL_120_TITLE = "树灵村落",
	LEVEL_121_HISTORY = "村落已经安全了，树灵族告诉我们说，在袭击发生之前，他们就感应到远古的封印已摇摇欲坠，这大概就是鳄鱼族人突然袭击的原因。带着这条线索，我们深入到了沼泽的中心，偶然发现了一个古老的树灵族石阵，它看起来像一个巢穴…某种巨大生物的巢穴。",
	LEVEL_121_TITLE = "沉没遗迹",
	LEVEL_122_HISTORY = "到达古老的神庙后，我们最担心的事情还是发生了。长久以来保护世界不受侵害，封印着“吞世者，噬界灾鳄”的法阵几乎已经瓦解，仅剩几名绝望的树灵族萨满在勉强维持。将军，阻止噬界灾鳄，否则整个王国都将落入他永不满足的大口之中。",
	LEVEL_122_TITLE = "极饿凶谷",
	LEVEL_123_HISTORY = "侦察兵报告称，邻近的山脉发生了异常的山体滑坡。进一步调查发现，罪魁祸首是一群陌生的矮人，他们正在山的南面组装一座巨型机器人。将军，请务必前去调查。",
	LEVEL_123_TITLE = "暗钢之门",
	LEVEL_124_HISTORY = "虽说矮人一直以发明而著称，但这个自称\"暗钢\"的部族对金属的执着已经走火入魔，甚至让博古尔手下的矮人都相形见绌，一炉接着一炉不停地炼造钢铁武装自己。这背后是谁搞的鬼？我们必须找出真相！",
	LEVEL_124_TITLE = "狂热组装厂",
	LEVEL_125_HISTORY = "正如我们所担心的那样，只有这座大山的内部才能容纳足以打造这等巨大机器人的锻炉。这里到底有多少矮人啊？那么多人在阻挡我们前进，却还有人在不停地锻造和焊接。更诡异的是，他们全都长得一模一样？这其中一定还隐藏着什么不可告人的秘密。",
	LEVEL_125_TITLE = "巨型核心",
	LEVEL_126_HISTORY = "我们在大山内外不断穿行，来到一个满是大缸的房间，这些缸里的东西可不得了。难怪这群矮人兵力充沛，技艺和样貌也像一个模子刻出来的。他们全都是同一个矮人——诡须！他利用邪恶的科学伎俩源源不断地制造自己的复制体。将军，我们必须阻止这一切！",
	LEVEL_126_TITLE = "克隆密室",
	LEVEL_127_HISTORY = "暗钢势力在这座山中的阴谋几乎已被我们成功遏止，但如果诡须仍然逍遥法外，一切都将付诸东流。他肯定正在完成最后工作，准备启动机器人的头部。将军，率领部队登上山顶，但愿这次我们能面对真正的诡须本人吧。",
	LEVEL_127_TITLE = "统治穹顶",
	LEVEL_128_HISTORY = "顺着侦察兵留下的线索，我们发现了那些阴魂不散的邪教徒的踪迹。看来他们又找了个新的神明来拜——一个邪恶的、织网的怪物……邪教徒加蜘蛛？这俩凑一块准没好事！",
	LEVEL_128_TITLE = "玷污神庙",
	LEVEL_129_HISTORY = "我们越往深处走，就越能清晰地感受到那股恐怖早已在暗处盘踞许久，只待时机成熟发动袭击。这周围蛛网密布，诡异的黑暗直逼脊背，我敢说我们离巢穴的核心不远了。",
	LEVEL_129_TITLE = "繁殖室",
	LEVEL_12_HEROIC = "英雄模式描述12",
	LEVEL_12_HISTORY = "我们的部队围住了邪恶巫师维兹南之塔。该把帐好好算一算...展开最后决战的时候到了。这是保卫王国安全的终极之战。我们一步一步走到现在；早已没有丝毫退路。\n\n现在是我们展现勇气的时刻！",
	LEVEL_12_IRON = "钢铁模式描述12",
	LEVEL_12_IRON_UNLOCK = "无火炮",
	LEVEL_12_MODES_UPGRADES = "等级5最高",
	LEVEL_12_TITLE = "黑暗之塔",
	LEVEL_130_HISTORY = "终于，我们到达了他们口中女神的巢穴——一座破败不堪、遗弃已久的神庙，在尘封的历史的重压之下已经摇摇欲坠。世人抛弃的神明确实配得上这般王座。必须彻底消灭这些害虫，一只不留。",
	LEVEL_130_TITLE = "遗忘王座",
	LEVEL_131_HISTORY = "历尽征战，王国重归和平。眼下只需聆听海浪拍岸，摆上一局围棋，静候一位老友。然而，就算眼前是一片风平浪静，我却唯恐这份和平时日无多……",
	LEVEL_131_TITLE = "仙界猴林",
	LEVEL_132_HISTORY = "我军追至火山深处，见一荒废古庙，此地曾是供奉烈焰之所。\n\n然而镇守熔岩深渊的赤炎神龙，本与世无争，如今却躁动不安，戾气冲天。此番异状，定是红孩儿施术惑其心志。",
	LEVEL_132_TITLE = "炎龙洞穴",
	LEVEL_133_HISTORY = "鏖战红孩儿后，我军一路前进，直抵怒风岛。才一登岸，飓风骤起，盘旋如蟒。此岛凶险万分，却是通往铁扇公主宫殿的必经之路！诸君戒备，风暴将至！",
	LEVEL_133_TITLE = "怒风岛",
	LEVEL_134_HISTORY = "先前历经万难，全拜公主铁扇所赐。我军冲破风暴，抵达风眼之地。此处楼台安然无恙，景致虽美，却暗藏杀机，切不可放松戒备！就算是那魔王的家室，也休得阻挡我军前行！",
	LEVEL_134_TITLE = "风暴之眼",
	LEVEL_135_HISTORY = "大战在即！牛魔王傲居金城之上，我军剩余部队，定以智勇之力，正面破敌！必须在他染指灵珠之前斩断祸根。\n为了山河社稷，为了天下苍生——联盟将士，列阵除魔！",
	LEVEL_135_TITLE = "魔王堡垒",
	LEVEL_136_HISTORY = "天空探险者们带来了令人不安的消息：在王国遥远的天穹之上，他们发现了一道尘封已久，刻印着古代文字的神秘魔法传送门。\n尽管那古老的文字已发出强烈的警示——'不得踏入云境之国'，国王与卫兹南仍然决定前往，誓要探明真相。",
	LEVEL_136_TITLE = "巨龙之门",
	LEVEL_137_HISTORY = "我们已穿过传送门，踏入云境之国。此行的使命已然明确：协助奥利昂，守护最后的'女王龙蛋'。为此我们必须前往守望者要塞——一座由体型娇小，但历经战斗的'守望者'所驻守的古老要塞。\n突然间，猛烈的轰鸣于前方震响，我们得加快脚步前往救援了。",
	LEVEL_137_TITLE = "守望者要塞",
	LEVEL_138_HISTORY = "历经一番苦战，我们终于夺回了守望者要塞，现在可以向'核心圣所'进军了——那里是'月龙'露娜莉丝镇守的圣地，负责在此守护女王龙蛋的安全。时间紧迫，但愿一切还来得及。",
	LEVEL_138_TITLE = "核心圣所",
	LEVEL_139_HISTORY = "露娜莉丝的战死与女王龙蛋的遗失，沉重打击了我们的士气，阴郁的气氛在将士们之间弥漫。直到国王迪纳斯的话语，让众人重新燃起了对抗魔龙人的斗志。\n如今我们抵达之处，是一座巨大的火山坑，也是怪物大军的源头；孤注一掷的时刻到了，这一战，我们将直捣黄龙，根除祸患！",
	LEVEL_139_TITLE = "龙人繁衍地",
	LEVEL_13_HEROIC = "英雄模式描述13",
	LEVEL_13_HISTORY = "将军！我们需要你和你勇敢的手下！维兹南即使死了，还是留下一堆麻烦。当你们与他交战时，他派遣一个部族唤醒了可怕的蜘蛛女王之一，萨雷格兹！\n\n我们本以为蜘蛛女王再也不会醒来，可是萨雷格兹凭借黑暗之力，接管了维兹南的残余部队。你必须消灭他们，干掉萨雷格兹！",
	LEVEL_13_IRON = "钢铁模式描述13",
	LEVEL_13_IRON_UNLOCK = "无火炮\n无法师塔",
	LEVEL_13_MODES_UPGRADES = "等级5最高",
	LEVEL_13_TITLE = "萨雷格兹的巢穴",
	LEVEL_140_HISTORY = "终焉将至。守望者法师们已然感知到，邪恶降临于远古的祭祀之地。提兰索尔正试图汲取龙蛋中王族血液的精华，成为无可争议的龙族之王。侦察部队将确认提兰索尔及其手下的确切位置，而我们也该整军备战，迎接最终的决战了。\n联盟，集结！",
	LEVEL_140_TITLE = "云国之冠",
	LEVEL_14_HEROIC = "英雄模式描述14",
	LEVEL_14_HISTORY = "利尼维亚守护者！王国虽然取得了和平，但邪恶永远不会消失！我们的密探报告称，阿卡洛斯遗迹遭到兽人和类哥布林大军的入侵。\n\n新的兽人军阀古拉克利用维兹南留下的权力真空，他的军队正对这片区域实施恐怖统治。\n\n你必须将这些入侵者从圣地赶出去！",
	LEVEL_14_IRON = "钢铁模式描述14",
	LEVEL_14_IRON_UNLOCK = "无弓箭塔\n无兵营",
	LEVEL_14_MODES_UPGRADES = "等级5最高",
	LEVEL_14_TITLE = "阿卡洛斯遗迹",
	LEVEL_15_HEROIC = "英雄模式描述15",
	LEVEL_15_HISTORY = "召唤你的部队，将军！黑暗力量无休无止地进攻我们深爱着的王国，我们必须采取行动。情报称，这片名为腐朽森林的区域确实无比腐朽；因为森林的中央打开了一扇通往地狱的传送门。\n\n死者在这片森林中得不到安息，植物也会对进入者恶意相向。你必须带领军队进入腐朽森林，找到问题的根源所在！",
	LEVEL_15_IRON = "钢铁模式描述15",
	LEVEL_15_IRON_UNLOCK = "无弓箭塔\n无火炮",
	LEVEL_15_MODES_UPGRADES = "等级5最高",
	LEVEL_15_TITLE = "腐朽森林",
	LEVEL_16_HEROIC = "英雄模式描述15",
	LEVEL_16_HISTORY = "将军，你必须再度领兵，保护我们的王国不受敌人侵犯！探子回报称，一批邪恶的罪犯正聚集到寂静森林的深处。没错，就是城民们鲜少敢于踏足的寂静森林...但你可不只是城民！\n\n马上率领军队进入森林，消灭这些恶棍。让他们为当初决定走上犯罪道路的那一天感到后悔！",
	LEVEL_16_IRON = "钢铁模式描述15",
	LEVEL_16_IRON_UNLOCK = "无弓箭塔\n无法师塔",
	LEVEL_16_MODES_UPGRADES = "等级5最高",
	LEVEL_16_TITLE = "寂静森林",
	LEVEL_17_HEROIC = "英雄模式描述15",
	LEVEL_17_HISTORY = "干得漂亮！你们成功赶走了那些卑鄙的的罪犯。你们汇集起来的战斗力，击溃了敌人绝大多数游击部队，不过他们正在逃向森林的更深处。我们有理由相信，里面还有一个他们的巢穴，战利品全部屯积在那儿。\n\n追上去，将他们从巢穴中引出来，夺回战利品。事先警告，如此成功的罪犯很可能有着精明的脱身计划！",
	LEVEL_17_IRON = "钢铁模式描述16",
	LEVEL_17_IRON_UNLOCK = "无法师塔\n无火炮",
	LEVEL_17_MODES_UPGRADES = "等级5最高",
	LEVEL_17_TITLE = "强盗的巢穴",
	LEVEL_18_HEROIC = "英雄模式描述15",
	LEVEL_18_HISTORY = "打包好你们的冬装，士兵们；我们即将启程前往冰川高地！当地人报告出现动乱，国王命令我们向高地进发，调查这些报告。小心点，因为高地可是很多准备不足的探险家们的冰封墓穴。\n\n你可能会在那儿冻死，前提是凶猛的哈克拉吉巨魔没有先干掉你！",
	LEVEL_18_IRON = "钢铁模式描述15",
	LEVEL_18_IRON_UNLOCK = "无弓箭塔\n无法师塔",
	LEVEL_18_MODES_UPGRADES = "等级5最高",
	LEVEL_18_TITLE = "冰川高地",
	LEVEL_19_HEROIC = "英雄模式描述15",
	LEVEL_19_HISTORY = "我们现在知道，北方动乱是由巨魔军阀阿古克汗引发的！这只卑鄙的野兽将所有哈克拉吉巨魔部族都归入到自己的血色旗帜之下！如果我们不设法阻止他，他的军队必定会从北方势如破竹，威胁到利尼维亚的善良城民。\n\n准备与哈克拉吉族的凶狠大军交战，到他们的地盘与他们的邪恶首领正面交锋！",
	LEVEL_19_IRON = "钢铁模式描述15",
	LEVEL_19_IRON_UNLOCK = "无兵营\n无法师塔",
	LEVEL_19_MODES_UPGRADES = "等级5最高",
	LEVEL_19_TITLE = "哈克拉吉高原",
	LEVEL_1_HEROIC = "英雄模式描述1",
	LEVEL_1_HISTORY = "你好，英勇而尊贵的战士！作为陛下军队的将军，迪纳斯国王需要你的帮助。\n\n南港市的居民报告称受到拦路强盗和其他不法歹徒的攻击。你必须带领一队人马前往南港，支援那座城市的防御。\n\n祝你好运，将军！",
	LEVEL_1_IRON = "钢铁模式描述1",
	LEVEL_1_IRON_UNLOCK = "无弓箭塔\n无法师塔",
	LEVEL_1_MODES_UPGRADES = "等级1最高\n无英雄",
	LEVEL_1_TITLE = "南港",
	LEVEL_201_HISTORY = "将军，我奉命回到过去，向利尼维亚国王发出警告……黑暗巫师卫兹南将带来毁灭性的未来。\n\n不过在我抵达的此刻，利尼维亚城堡正遭受强盗的围攻，眼下还是先清除强盗的威胁吧！",
	LEVEL_201_TITLE = "利尼维亚城堡",
	LEVEL_202_HISTORY = "若是向东行进，势必要经过 “强盗巢穴”，以我军目前的状况，恐怕还难以应付。不如向西行进，前往 “奥术魔法学院” 招募伙伴吧。\n\n这里似乎也面临着强盗的威胁！如果我们能够出手相助的话，肯定能找到愿意加入我们的盟友！",
	LEVEL_202_TITLE = "奥术魔法学院",
	LEVEL_203_HISTORY = "根据当地农民的说法，数月以来，他们一直遭到名为 “暗影兵团” 的组织袭击，就连负责送信求助的信使也惨遭毒手。\n\n将军，请让我们暂缓行程，帮助这里的居民吧，就算会耽搁任务，但这是正义之举。",
	LEVEL_203_TITLE = "遭受入侵的农田",
	LEVEL_204_HISTORY = "矮人族是以战士和工程师而闻名的民族。他们奉国王之命，正在此建造巨大的防壁，阻挡利尼维亚以西那片蛮荒之地中潜藏的威胁。\n\n目前防壁已经接近完工，就让我们协助完成最后的守卫工作吧，事成之后也许还能借此说服矮人加入我们的远征。",
	LEVEL_204_TITLE = "西部防壁",
	LEVEL_205_HISTORY = "对精灵而言，宏伟的银色橡树向来是他们与自然联系的重要象征。作为盟友，面对卫兹南的威胁他们一定会出手相助。\n\n然而兽人似乎也加入了卫兹南的势力，正准备在银橡村中大肆破坏……我们绝不能让他们得逞！",
	LEVEL_205_TITLE = "银橡村",
	LEVEL_206_HISTORY = "在发展为繁华的城市前，“洛扎贡”曾是大魔法师“纽维斯”及其弟子的居所。\n\n从纽维斯的口中，我们得知了一条能够穿越暴云山脉的隐秘路径，若是从那里走，就能避开卫兹南的眼线……然而就在谈话之际，暗影兵团的进攻就到来了。",
	LEVEL_206_TITLE = "洛扎贡之塔",
	LEVEL_207_HISTORY = "吹响号角，准备迎敌！我们遭到突袭了，敌军在不知不觉间从三面包围了我们的营地。\n\n将军，快去集结将士们抵挡兽人与强盗的进攻吧，必须争取让其余部队完成整备的时间。后续就在阿卡洛斯城门口会合吧，祝你好运！",
	LEVEL_207_TITLE = "三面伏击",
	LEVEL_208_HISTORY = "通往暴云山脉地下通道的唯一入口，就隐藏在这座宏伟的阿卡洛斯要塞之下。驻扎在此地的圣殿骑士是我们的盟友，也愿意全力帮助我们。\n\n不过，我们必须抓紧时间。要是在这里停留过久，恐怕会引起卫兹南的注意，让阿卡洛斯陷入危难之中。",
	LEVEL_208_TITLE = "阿卡洛斯要塞",
	LEVEL_209_HISTORY = "这条险峻的道路虽说能够穿越山脉，从内部抵达 “暴云寺院”，但途中我们可以说是与世隔绝了。\n\n这……居住在此且领地意识极强的巨魔族除外，我们必须做好最坏的打算，他们显然是不会给我们好脸色看的。",
	LEVEL_209_TITLE = "险峻路途",
	LEVEL_20_HEROIC = "英雄模式描述15",
	LEVEL_20_HISTORY = "恶魔们消灭了我们驻扎在维兹南之塔的部队，只留下一个幸存者...从他受到惊吓的胡言乱语中，我们了解到，这些穷凶极恶的部落是从灰烬裂缝的深渊中爬上来的。\n\n将军，你必须保障这一带的安全，找到威胁来源，确保我们真正击败了维兹南。",
	LEVEL_20_IRON = "钢铁模式描述15",
	LEVEL_20_IRON_UNLOCK = "无法师塔",
	LEVEL_20_MODES_UPGRADES = "等级5最高",
	LEVEL_20_TITLE = "火焰之坑",
	LEVEL_210_HISTORY = "在巨魔的追击之下，我们抵达了一处开阔的石窟。阳光从洞外渗了进来，洒落在广阔而冰封的湖面上。\n\n眼前的美景令人屏息……然而，散落在四周的众多尸骨，却暗示着这里恐怕是某种怪物的危险巢穴。压低声响，尽快通过此处吧。",
	LEVEL_210_TITLE = "雪怪巢穴",
	LEVEL_211_HISTORY = "在湖泊之后，我们落入了山中的深处。空气里一片死寂，伸手不见五指的黑暗，笼罩在这洞窟之中。\n\n让人熟悉的窸窸窣窣声响从洞穴的通道间传来，缓缓包围了我们的部队。赶紧搭建营地做好准备，敌人随时都会朝我们攻来！",
	LEVEL_211_TITLE = "极冻深巢",
	LEVEL_212_HISTORY = "通往暴云寺院的道路，不仅充满了陡峭的爬坡和险峻的悬崖……这回更是直接将我们引向了巨魔的老巢。\n\n既然他们已经占尽地利，我们就更应该时刻保持警惕，以防他们带给我们什么 “惊喜”。打起精神来，将军！",
	LEVEL_212_TITLE = "哈克拉吉村",
	LEVEL_213_HISTORY = "啊！终于！新鲜的空气！暴云寺院的术士们热情地欢迎我们的到来，同时向我们展示了寺院最新建成的防御设施—— “日光之塔”。\n\n然而现在还不是能够放松警惕的时候……为了摧毁这座塔，巨魔大军正蜂拥而至，残暴的巨魔之王更紧随其后。保卫祭坛，准备迎战吧！",
	LEVEL_213_TITLE = "暴云寺院大堂",
	LEVEL_214_HISTORY = "旅程的下一站，我们抵达了瓦拉杜勒。这里是布莱克本领主的封地，他们长期对抗着古老的诅咒——此地的死者始终无法安息。\n\n然而，就连此地的光芯镇也遭到了卫兹南大军的袭击，卫兹南的意图不言而喻，就连我们潜在的盟友，也已经成为他的目标。",
	LEVEL_214_TITLE = "光芯镇",
	LEVEL_215_HISTORY = "伴随着卫兹南的黑暗大军不断壮大，布莱克本军节节败退，如今只能退守至领主城堡，将其作为最后的防线。\n\n布莱克本告诉我们，有位与之交好的女巫调配了特殊的药水，能够让他吸收这片土地与人民所承载的诅咒，将其转换为纯粹的力量……将军，直觉告诉我，这肯定不是什么好主意。",
	LEVEL_215_TITLE = "布莱克本城堡",
	LEVEL_216_HISTORY = "在卫兹南爪牙的影响下，瓦拉杜勒的诅咒不断加剧。这片美丽的林地仍在顽强抵抗腐化……然而，黑暗大军的增援迟早会使此地沦陷。\n\n生性善良的树精族居住于此，一旦被黑暗侵蚀，他们将再也无法恢复原状。挺身而出，阻止黑暗的入侵吧！",
	LEVEL_216_TITLE = "金色林地",
	LEVEL_217_HISTORY = "怀抱着寻求支援与喘息的渴望，我们来到了圣骑士的总部，然而这里却并不平静……一场暴乱正在发生，部分圣骑士堕入邪道，与卫兹南军联手发起了这场叛乱。\n\n不能再让黑暗势力继续扩大下去了，帮助圣骑士们保卫圣域吧！",
	LEVEL_217_TITLE = "圣骑士圣域",
	LEVEL_218_HISTORY = "我们及时抵达了阿坎尼亚城，卫兹南还未能实现让灰烬裂缝彻底敞开的邪恶计划。不过，城市的这片寂静……也太不寻常了。\n\n无论如何，眼下我们唯一的使命，就是击溃卫兹南的军队，并摧毁 “艾纳妮之泪”。将未来的历史导向正途吧！",
	LEVEL_218_TITLE = "卫兹南之塔",
	LEVEL_21_HEROIC = "英雄模式描述15",
	LEVEL_21_HISTORY = "我们要面对的是大恶魔头领之一的摩洛克。我们的贤者已经发现，打开通往万魔殿传送门的人就是他，那里简直是如同地狱一般可怕的异界。\n\n你发誓跟随国王，哪怕是遁入地狱...现在，你要去的就是那儿...",
	LEVEL_21_IRON = "钢铁模式描述15",
	LEVEL_21_IRON_UNLOCK = "无火炮",
	LEVEL_21_MODES_UPGRADES = "等级5最高",
	LEVEL_21_TITLE = "万魔殿",
	LEVEL_22_HEROIC = "英雄模式描述15",
	LEVEL_22_HISTORY = "邪恶没有片刻安歇...所以正义之师也无瑕休整。信鹰从腐朽森林的精灵要塞带来了消息。整座森林仍被邪恶腐蚀，我们的精灵盟友正全力抵挡可怕的怪物。\n\n新的黑暗力量正在崛起，试图将势力范围拓展到森林以外的区域。赶快行动吧，将军，我们必须动身支援精灵朋友们，将邪恶从那片远古森林中永远消灭！",
	LEVEL_22_IRON = "钢铁模式描述15",
