	LEVEL_2_TITLE = "郊原",
	LEVEL_30_HEROIC = "英雄模式描述3",
	LEVEL_30_HISTORY = "萨佩绿洲的战斗似乎只是佯攻，魔王马拉加尔已经向海盗老巢逃去了。\n\n我们别无选择，只能穿过危险的绝望沙丘。没时间绕路了，当心脚下的流沙，那里面好似藏着神秘的怪兽，夺走了无数经验丰富的探险家的性命！",
	LEVEL_30_IRON = "钢铁模式描述3",
